const M=(q,o,e,d)=>({k:'m',q,o,e,d:d||'m'}),S_=(q,g,m,n,d)=>({k:'s',q,g,m,n,d:d||'m'}),GQ=(q,chk,svg,d)=>({k:'g',q,chk,svg,d:d||'h'});
const SB=[
{id:'rs',n:'Religious Studies',b:'AQA A-Level',ic:'🕊️',col:'#7c3aed',note:'Check coverage against the AQA specification',th:[
{n:'Philosophy of Religion',t:[{id:'rs1',n:'Arguments for the existence of God',sum:`<b>A priori</b> = from reason alone (Ontological: Anselm, Descartes; criticised by Gaunilo, Kant: existence is not a predicate). <b>A posteriori</b> = from experience (Cosmological: Aquinas Five Ways, first cause; Teleological: Paley watch analogy, Aquinas design). <b>Criticisms:</b> Hume (universe is unique, analogy weak), Darwin/evolution, Big Bang, Russell (universe is a brute fact).`,q:[
M("Who presented the ontological argument in his Proslogion?",["Anselm","Aquinas","Paley","Hume"],"Anselm argued God is 'that than which nothing greater can be conceived', so must exist in reality as well as in the mind."),
M("Gaunilo criticised Anselm using which analogy?",["The perfect island","The watchmaker","The unmoved mover","The hedonic calculus"],"Gaunilo said you could 'define' a perfect island into existence, which is absurd, so the logic must fail."),
M("Which analogy does Paley use in his teleological argument?",["A watch found on a heath","A perfect island","A chain of dominoes","A ship in a storm"],"The watch's complexity and purpose imply a designer; so does the order of the universe."),
M("Why is Aquinas' cosmological argument called a posteriori?",["It starts from observation of the world","It starts from the definition of God","It relies on faith alone","It cannot be criticised"],"A posteriori arguments rely on experience, e.g. observing motion and causation."),
M("Which criticism did Kant make of the ontological argument?",["Existence is not a predicate","Design implies a designer","Evil disproves God","Pleasure is the only good"],"Existence adds nothing to the concept of a thing, so it cannot be part of God's definition."),
S_("Explain Hume's criticism of the design argument.",[["analogy","disanalog","not like a machine"],["unique","only one universe","one-off"],["many designers","imperfect","chance","evolution","epicurean","other explanation"]],"The universe is not enough like a machine for the analogy to work; it is unique so we cannot infer its cause; order could come from chance or many/imperfect designers.",2),
S_("Define an a priori argument.",[["before","without","independent","prior"],["experience","observation","evidence","empirical"],["logic","reason","deduc","definition"]],"An a priori argument is based on reason alone, independent of experience, e.g. the ontological argument.",2)]},{id:'rs3',n:'Evil and suffering',sum:`<b>Problem of evil:</b> if God is all-powerful and all-loving, why is there evil? <b>Logical</b> (Mackie: inconsistent triad) vs <b>evidential</b> (too much evil). <b>Natural</b> evil (earthquakes) vs <b>moral</b> evil (human choices). <b>Theodicies:</b> Augustine (evil is a privation of good, caused by the Fall and free will); Irenaeus/Hick (soul-making: suffering helps us grow); Process theology (God is not omnipotent). Criticisms: Augustine clashes with evolution; is the amount of suffering really needed?`,q:[M(`Which theodicy says evil is a privation of good caused by the Fall?`,[`Augustine`,`Irenaeus`,`Mackie`,`Process theology`],`Augustine: God made a perfect world; evil entered through human free will and the Fall.`),M(`Hick's soul-making theodicy says suffering...`,[`Helps humans develop morally and spiritually`,`Only punishes sin`,`Proves God does not exist`,`Is an illusion`],`Hick (after Irenaeus): the world is a place for spiritual growth, which needs challenge.`),M(`The inconsistent triad is associated with...`,[`Mackie`,`Hick`,`Augustine`,`Paley`],`Mackie: God cannot be omnipotent, omnibenevolent and allow evil all at once.`),S_(`Explain one criticism of Augustine's theodicy.`,[[`evolution`,`science`,`scientific`,`not literal`],[`free will`,`responsib`,`god created`,`foreknow`,`omniscient`],[`hell`,`punish`,`unfair`,`natural evil`]],`Evolution shows no historical Fall; a perfect creation that went wrong implies God foresaw it; natural evil is not explained by human free will; hell seems unjust.`,2)]},{id:'rs4',n:'Religious experience',sum:`<b>Types:</b> conversion, mystical (union with God), visions, corporate, numinous (Otto: awe and fascination). <b>James:</b> mystical experiences are ineffable, noetic, transient and passive. <b>Swinburne:</b> principle of credulity (trust experience unless there is reason not to) and testimony. <b>Challenges:</b> Freud (wish-fulfilment), Persinger (brain stimulation), Hume (unreliable testimony), subjectivity.`,q:[M(`Who described the numinous?`,[`Otto`,`Swinburne`,`James`,`Freud`],`Otto: the mysterium tremendum et fascinans, an experience of the wholly other.`),M(`Which is one of William James' characteristics of mystical experience?`,[`Ineffability`,`Rationality`,`Permanence`,`Verifiability`],`James: ineffable, noetic, transient, passive.`),M(`Swinburne's principle of credulity says...`,[`We should accept what seems to be the case unless there is good reason not to`,`Religious claims need empirical proof`,`Experiences must be shared by a group`,`Miracles break natural laws`],`So religious experiences should be taken as genuine by default.`),S_(`Explain one challenge to the reliability of religious experience.`,[[`freud`,`wish`,`psycholog`,`delusion`],[`brain`,`neuro`,`persinger`,`temporal`,`drug`],[`verify`,`subjective`,`evidence`,`testimony`,`hume`]],`Freud: wish-fulfilment; Persinger: brain stimulation can cause similar experiences; experiences are subjective and cannot be verified.`,2)]},{id:'rs5',n:'Religious language',sum:`<b>Cognitive</b> language makes claims that can be true or false; <b>non-cognitive</b> does not. <b>Via negativa:</b> only say what God is not. <b>Analogy</b> (Aquinas). <b>Symbol</b> (Tillich). <b>Verification</b> (Ayer): meaningful only if analytic or empirically verifiable, so God-talk is meaningless. <b>Falsification</b> (Flew: gardener parable; Hare: bliks; Mitchell: stranger). <b>Language games</b> (Wittgenstein): meaning comes from use within a community.`,q:[M(`The verification principle says a statement is meaningful only if it is...`,[`Analytic or empirically verifiable`,`Emotionally moving`,`Approved by scripture`,`Logically possible`],`Ayer and the Vienna Circle: religious claims fail this test.`),M(`Flew's gardener parable argues religious claims...`,[`Are qualified until they assert nothing`,`Are verified by science`,`Are analytic truths`,`Are always symbolic`],`The believer keeps adding qualifications: death by a thousand qualifications.`),M(`Which theologian argued we can speak of God by analogy?`,[`Aquinas`,`Tillich`,`Ayer`,`Wittgenstein`],`Aquinas: analogy of attribution and proportion.`),S_(`Explain what is meant by language games.`,[[`wittgenstein`],[`context`,`use`,`community`,`meaning`,`rules`],[`different`,`own rules`,`religious`,`believers`]],`Wittgenstein: language gets meaning from how it is used in a particular community, so religious language has its own rules and cannot be judged by science.`,2)]},{id:'rs6',n:'Miracles',sum:`<b>Aquinas:</b> an act of God beyond natural order. <b>Hume:</b> a violation of a law of nature. <b>Holland:</b> a remarkable coincidence interpreted religiously. <b>Wiles:</b> God acts in the world as a whole, not particular events. <b>Hume's arguments:</b> laws of nature rest on uniform experience; testimony is unreliable; miracles are reported by the ignorant; rival religions cancel out. <b>Swinburne:</b> miracles are possible if there is good evidence. <b>Problem:</b> why does God not prevent great suffering?`,q:[M(`Hume defined a miracle as...`,[`A violation of a law of nature`,`A coincidence interpreted religiously`,`A natural event`,`Always a sign from the devil`],`Hume: a transgression of a law of nature by God or an invisible agent.`),M(`Holland defined a miracle as...`,[`A remarkable coincidence interpreted religiously`,`A violation of nature`,`An event only Catholics can see`,`Caused by physics alone`],`Holland: the event can be natural but is taken as religiously significant.`),M(`Which scholar argued God acts in the world as a whole rather than in particular events?`,[`Wiles`,`Hume`,`Aquinas`,`Swinburne`],`Wiles avoids the problem of why God does not intervene more often.`),S_(`Explain one of Hume's arguments against miracles.`,[[`law of nature`,`laws of nature`,`uniform`,`regular`],[`testimony`,`witness`,`reliable`,`unreliable`],[`ignorant`,`wonder`,`religion`,`contradict`]],`Laws of nature are based on uniform experience, and testimony for miracles is less reliable than that experience (witnesses are often credulous or biased).`,2)]}]},
{n:'Ethics',t:[{id:'rs7',n:'Natural Law',sum:`<b>Natural Law</b> (Aquinas): reason works out right and wrong from our God-given purpose (telos). <b>Primary precepts:</b> preserve life, reproduce, educate, live in society, worship God. <b>Secondary precepts</b> are rules applied from these. <b>Double effect:</b> a bad side effect is allowed if foreseen but not intended. <b>Strengths:</b> universal, based on reason. <b>Weaknesses:</b> assumes a purpose, rigid (e.g. contraception), Hume: cannot derive ought from is.`,q:[M(`Which is a primary precept of Natural Law?`,[`Preserve life`,`Maximise pleasure`,`Pay taxes`,`Always tell the truth`],`The five primary precepts are life, reproduction, education, society and worship.`),M(`Which scholar developed Christian Natural Law?`,[`Aquinas`,`Bentham`,`Fletcher`,`Kant`],`Aquinas built on Aristotle and the idea of telos.`),M(`The doctrine of double effect says an action with a bad side effect can be right if...`,[`The bad effect was foreseen but not intended`,`The consequences are good`,`The Church approves`,`Pleasure is maximised`],`Intention matters: the good effect must be the aim.`),S_(`Explain one criticism of Natural Law.`,[[`hume`,`ought`,`naturalistic`],[`purpose`,`telos`,`assumes`,`god`],[`rigid`,`inflexible`,`contracepti`,`absolute`,`change`]],`It assumes humans have a fixed purpose; Hume says you cannot get ought from is; its rules can be rigid, e.g. on contraception.`,2)]},{id:'rs2',n:'Utilitarianism',sum:`<b>Act utilitarianism</b> (Bentham): the right act brings the greatest happiness to the greatest number; use the <b>hedonic calculus</b>. <b>Mill:</b> higher and lower pleasures. <b>Rule utilitarianism:</b> follow rules that generally maximise happiness. <b>Preference</b> (Singer). <b>Criticisms:</b> tyranny of the majority, ignores rights and justice, hard to predict consequences.`,q:[
M("Who developed act utilitarianism?",["Bentham","Mill","Kant","Aquinas"],"Jeremy Bentham: right actions maximise pleasure and minimise pain."),
M("How did Mill refine Bentham's theory?",["By distinguishing higher and lower pleasures","By ranking pleasures by duration only","By rejecting consequences","By adding divine commands"],"Mill argued intellectual pleasures are higher in quality: better Socrates dissatisfied than a fool satisfied."),
M("Which is one of Bentham's hedonic calculus factors?",["Propinquity","Piety","Duty","Sanctity"],"The calculus includes intensity, duration, certainty, propinquity, fecundity, purity and extent."),
M("How does rule utilitarianism differ from act utilitarianism?",["It judges rules by their general utility","It ignores happiness","It judges each act alone","It uses divine law"],"Rule utilitarians follow rules that generally maximise happiness, avoiding some act-utilitarian injustices."),
M("Which philosopher is associated with preference utilitarianism?",["Peter Singer","Jeremy Bentham","John Rawls","Anselm"],"Singer: maximise the satisfaction of people's preferences, not just pleasure."),
S_("Explain one criticism of utilitarianism.",[["majority","minority","tyranny"],["justice","rights","innocent","unfair"],["predict","calculate","unknown","future"]],"It can sacrifice a minority for majority happiness, ignoring justice and rights; or consequences cannot be reliably predicted or calculated.",2),
S_("State the principle of utility.",[["greatest","most","maximi"],["happiness","pleasure","utility","good"],["number","people","majority"]],"Actions are right if they bring the greatest happiness to the greatest number.",2)]}]},{n:'Buddhism (Study of Religion)',t:[{id:'b1',n:'Four Noble Truths and the Three Marks',sum:`<b>Four Noble Truths:</b> 1 dukkha (life involves suffering or dissatisfaction); 2 samudaya (cause = craving/tanha); 3 nirodha (it can end = nirvana); 4 magga (the path = Eightfold Path). <b>Three marks:</b> anicca (impermanence), dukkha, anatta (no fixed self). <b>Nirvana:</b> the fires of greed, hatred and ignorance go out, ending samsara (rebirth). Check the AQA spec for the exact scholars and sources.`,q:[M(`What does anatta mean?`,[`No permanent fixed self`,`Impermanence`,`Suffering`,`Enlightenment`],`Anatta: there is no unchanging soul; the self is made of changing parts.`),M(`The Second Noble Truth says the cause of dukkha is...`,[`Craving (tanha)`,`Sin`,`Gods will`,`Poverty`],`Craving and attachment keep beings in samsara.`),M(`Which is one of the Three Marks of Existence?`,[`Anicca`,`Moksha`,`Atman`,`Puja`],`Anicca, dukkha and anatta.`),S_(`Explain the Four Noble Truths.`,[[`suffering`,`dukkha`,`dissatisf`],[`craving`,`tanha`,`desire`,`attachment`],[`cessation`,`end`,`nirvana`,`nibbana`],[`eightfold`,`path`,`magga`]],`Life involves dukkha; its cause is craving; it can end (nirvana); the way is the Eightfold Path.`,3)]}]}]},
{id:'eco',n:'Economics',b:'Pearson Edexcel A',ic:'📈',col:'#0891b2',note:'Themes 3 and 4 still to be added; check against the Edexcel A specification',th:[
{n:'Theme 1: Introduction to markets and market failure (Micro)',t:[{id:'e1',n:'Price elasticity of demand',sum:`<b>PED = %change in quantity demanded / %change in price.</b> Elastic (above 1 ignoring sign): quantity changes more than price. Inelastic (below 1): less. <b>Factors:</b> substitutes, necessity, share of income, time. <b>Revenue:</b> raise price if inelastic, cut price if elastic. <b>YED:</b> positive = normal, negative = inferior.`,q:[
M("What is the formula for price elasticity of demand?",["%change in Qd / %change in price","%change in price / %change in Qd","Change in Qd / change in price","Revenue / price"],"PED measures how responsive quantity demanded is to a price change."),
M("Price rises 10% and quantity demanded falls 25%. What is PED?",["-2.5","-0.4","-15","+2.5"],"-25 / 10 = -2.5, so demand is price elastic (greater than 1 ignoring the sign)."),
M("If demand is price elastic, a price rise will cause total revenue to...",["Fall","Rise","Stay the same","Double"],"Quantity falls proportionately more than price rises, so revenue falls."),
M("Which makes demand for a good more price elastic?",["More close substitutes","It is a necessity","Small share of income","Short time period"],"Easy alternatives let consumers switch away when price rises."),
M("A negative income elasticity of demand (YED) indicates a...",["Inferior good","Luxury good","Normal necessity","Complement"],"Demand falls as incomes rise for inferior goods."),
S_("Price falls from £10 to £8 and quantity demanded rises from 100 to 130. Calculate PED.",[["1.5"]],"%change in P = -20%, %change in Q = +30%. PED = 30 / -20 = -1.5 (elastic).",1),
S_("Explain why demand for petrol is price inelastic.",[["substitute"],["necessity","essential","need","commut"],["habit","addict","small proportion"]],"Few close substitutes and it is a necessity for many (commuting), so quantity demanded changes little when price rises.",2)]}]},
{n:'Theme 2: The UK economy - performance and policies (Macro)',t:[{id:'e2',n:'Inflation',sum:`<b>Inflation</b> = sustained rise in the general price level (UK target: 2% CPI). <b>Demand-pull:</b> AD grows faster than AS. <b>Cost-push:</b> SRAS shifts left. <b>Costs:</b> menu costs, shoe leather, falling real incomes, lost competitiveness. <b>Controls:</b> higher interest rates (monetary), tax rises or spending cuts (fiscal), supply-side policy. <b>Calculation:</b> (new - old) / old x 100.`,q:[
M("Which measure does the UK use for its inflation target?",["CPI","GDP deflator only","Unemployment rate","Balance of payments"],"The Bank of England targets 2% CPI inflation."),
M("Demand-pull inflation is caused mainly by...",["Aggregate demand growing faster than supply","Rising raw material costs","Falling wages","A fall in the money supply"],"Excess AD pulls up the price level when capacity is limited."),
M("Which is an example of cost-push inflation?",["A rise in oil prices","A cut in income tax","A rise in consumer confidence","Higher exports"],"Higher input costs shift SRAS left, raising prices."),
M("Which is an example of menu costs?",["Firms reprinting price lists","Consumers visiting more shops","Savers losing real value","Banks raising rates"],"Menu costs are the costs to firms of changing prices."),
M("Deflation is...",["A sustained fall in the general price level","A fall in the rate of inflation","A fall in GDP","A rise in unemployment"],"A fall in the rate of inflation is disinflation; deflation is falling prices."),
S_("Explain how a rise in interest rates could reduce inflation.",[["borrowing","saving"],["consumption","spending","investment","demand"],["mortgage","exchange rate","appreciat"]],"Higher rates raise the cost of borrowing and reward saving, so consumption and investment fall and AD grows more slowly. Mortgage payments rise and the exchange rate may appreciate, lowering import prices.",2),
S_("CPI rises from 120 to 126. Calculate the inflation rate.",[["5"]],"(126 - 120) / 120 x 100 = 5%.",1)]}]},{n:'Theme 3: Business behaviour and the labour market (Micro)',t:[{id:'e3',n:'Market structures',sum:`<b>Perfect competition:</b> many firms, identical goods, free entry, price takers. <b>Monopoly:</b> one dominant firm (25%+ share in the UK), high barriers, price maker. Can exploit consumers but may have economies of scale and fund R&D. <b>Profit max:</b> where MC = MR. <b>Oligopoly:</b> few firms, interdependent, collusion or price wars. <b>Contestable:</b> low barriers keep prices down.`,q:[M(`A firm maximises profit where...`,[`MC = MR`,`AR = AC`,`MR = 0`,`TR is highest`],`Producing one more unit adds more to cost than revenue beyond this point.`),M(`Which is a feature of monopoly?`,[`High barriers to entry`,`Many price-taking firms`,`Identical products only`,`Zero profit in the long run`],`Barriers let a monopoly keep supernormal profit.`),M(`In the UK a firm may be investigated as a monopoly with a market share of at least...`,[`25%`,`10%`,`50%`,`75%`],`The CMA uses 25% as a guide.`),S_(`Evaluate whether monopoly is always bad for consumers.`,[[`higher price`,`exploit`,`restrict output`,`inefficien`],[`economies of scale`,`lower cost`,`scale`],[`r&d`,`innovat`,`invest`,`dynamic`,`supernormal`],[`regulat`,`cma`,`price cap`,`depends`]],`Bad: higher prices, restricted output, inefficiency. Good: economies of scale can lower costs; supernormal profit funds R&D. It depends on regulation and the market.`,3)]}]},{n:'Theme 4: A global perspective (Macro)',t:[{id:'e4',n:'Exchange rates and trade',sum:`<b>Exchange rate:</b> price of one currency in another. <b>Appreciation:</b> exports dearer, imports cheaper. <b>Depreciation:</b> exports cheaper, imports dearer, may raise inflation. <b>Comparative advantage:</b> lowest opportunity cost, so specialise and trade. <b>Protectionism:</b> tariffs (tax on imports), quotas, subsidies; protects infant industries but raises prices. <b>Balance of payments:</b> current, capital and financial accounts.`,q:[M(`A depreciation of the pound is likely to...`,[`Make UK exports cheaper abroad`,`Make imports cheaper`,`Reduce inflation`,`Reduce export demand`],`Cheaper exports raise demand but imports cost more.`),M(`A tariff is...`,[`A tax on imports`,`A limit on quantity imported`,`A subsidy to exporters`,`A tax on exports`],`Tariffs raise the price of imports to protect domestic firms.`),M(`Comparative advantage is when a country...`,[`Has the lowest opportunity cost of producing a good`,`Produces the most of everything`,`Has the lowest wages`,`Has the biggest economy`],`Specialising where opportunity cost is lowest makes trade beneficial.`),S_(`Explain one effect of an appreciation of the pound on UK firms.`,[[`export`],[`dearer`,`expensive`,`less competitive`,`fall in demand`,`higher price`],[`import`,`cheaper`,`raw material`,`cost`]],`Exports become more expensive abroad so demand falls; imported raw materials become cheaper, lowering costs.`,2)]}]}]},
{id:'med',n:'Media Studies',b:'OCR A-Level',ic:'🎬',col:'#db2777',note:'Set products not yet added; check theorists against the OCR specification',th:[
{n:'Media language',t:[{id:'m1',n:'Media language and theory',sum:`<b>Barthes:</b> denotation (literal) vs connotation (associated meaning). <b>Saussure:</b> sign = signifier + signified. <b>Todorov:</b> equilibrium, disruption, recognition, repair, new equilibrium. <b>Levi-Strauss:</b> binary oppositions (good/evil). <b>Neale:</b> genre = repetition and difference. Use these to analyse camerawork, editing, mise-en-scene, sound and layout.`,q:[
M("In semiotics, what is connotation?",["The associated or cultural meaning of a sign","The literal meaning of a sign","A type of narrative","The audience's age"],"Barthes: denotation is literal; connotation is the wider meaning attached to it."),
M("Which stage comes after disruption in Todorov's narrative theory?",["Recognition","New equilibrium","Repair","Opening"],"Order: equilibrium, disruption, recognition, repair, new equilibrium."),
M("Levi-Strauss' theory of binary oppositions says meaning is created through...",["Conflict between opposites","Repetition and difference","Audience reception","Industry ownership"],"E.g. good/evil or hero/villain structure narratives."),
M("Neale argued genre is defined by...",["Repetition and difference","Binary oppositions","The hypodermic needle","Cultivation"],"Genres repeat familiar conventions but vary them to stay fresh."),
M("In Saussure's model, a sign consists of...",["Signifier and signified","Equilibrium and disruption","Encoding and decoding","Hero and villain"],"The signifier is the form; the signified is the concept."),
S_("Explain the difference between denotation and connotation.",[["literal","what you see","obvious","describe"],["associat","cultural","implied","symbol","ideolog"]],"Denotation is the literal, descriptive meaning of a sign; connotation is the associated cultural or ideological meaning.",2),
S_("Outline Todorov's narrative structure.",[["disruption","disequilibrium"],["recognition","realis","realiz"],["repair","resolution","restor"],["equilibrium"]],"Equilibrium, disruption, recognition of the disruption, repair, then a new equilibrium.",3)]}]},
{n:'Representation and audiences',t:[{id:'m2',n:'Representation and audiences',sum:`<b>Hall:</b> representation is constructed (re-presents reality); reception theory = preferred, negotiated, oppositional readings. <b>Gerbner:</b> cultivation (heavy viewing shapes your view of reality). <b>Shirky:</b> end of audience (users produce too). <b>Butler:</b> gender performativity. <b>Stereotype:</b> simplified, widely repeated image of a group.`,q:[
M("Hall's theory of representation suggests the media...",["Re-present reality rather than reflect it","Simply mirror reality","Have no effect","Only entertain"],"Representations are constructed through choices, so meanings are produced, not simply found."),
M("What does Gerbner's cultivation theory claim?",["Long-term heavy viewing shapes perceptions of reality","One programme changes behaviour instantly","Audiences always reject messages","Genres never change"],"E.g. mean world syndrome: heavy viewers overestimate danger."),
M("In Hall's reception theory, a negotiated reading is when the audience...",["Accepts some of the message but modifies it","Fully accepts the message","Rejects it entirely","Does not notice it"],"The three readings are preferred, negotiated and oppositional."),
M("Shirky's 'end of audience' argues that...",["Audiences are now also producers of media","Audiences are passive","Audiences have left TV","Only industries create media"],"Social media lets users create and share content."),
M("Butler's theory of gender performativity says gender is...",["Performed through repeated acts","Fixed at birth","Irrelevant to media","Created only by law"],"Identity is constructed by repeated performance, which media can reinforce or challenge."),
S_("What is meant by a stereotype?",[["simplif","generali","fixed"],["group","type of people","people"],["widely","repeated","assumption","common"]],"A stereotype is a simplified, widely held and repeated representation of a group of people.",2),
S_("Briefly explain Gerbner's cultivation theory.",[["long-term","heavy","repeated","over time"],["perception","view of the world","reality","mean world"]],"Long-term, heavy exposure to media cultivates a distorted view of reality, e.g. mean world syndrome.",2)]}]},{n:'Media industries',t:[{id:'m3',n:'Media industries',sum:`<b>Curran and Seaton:</b> a few powerful conglomerates control much of the media. <b>Livingstone and Lunt:</b> regulation protects citizens and consumers (Ofcom, BBFC, ASA, IPSO, PEGI) but is challenged online. <b>Hesmondhalgh:</b> cultural industries are risky, so firms integrate. <b>Terms:</b> conglomerate, vertical and horizontal integration, public service broadcasting, convergence.`,q:[M(`Curran and Seaton argue that...`,[`A few powerful companies control much of the media`,`Audiences control the media`,`Media has no effect`,`All media is state-owned`],`Ownership concentration shapes what we see.`),M(`Vertical integration is when a company...`,[`Owns several stages of production and distribution`,`Buys rivals in the same sector`,`Is publicly funded`,`Has no regulation`],`E.g. making and distributing its own products.`),M(`Which body rates video games sold in the UK?`,[`PEGI`,`IPSO`,`Ofcom`,`ASA`],`PEGI gives age ratings for games.`),S_(`Explain what is meant by media regulation and why it matters.`,[[`rules`,`control`,`law`,`monitor`,`protect`],[`harm`,`offensive`,`audience`,`children`,`standards`],[`ofcom`,`bbfc`,`asa`,`ipso`,`pegi`]],`Regulation means rules and bodies (e.g. Ofcom, BBFC) that monitor media to protect audiences, especially children, from harm and keep standards.`,2)]}]},{n:'Further theories',t:[{id:'m4',n:'Propp, Baudrillard, Gauntlett, van Zoonen, Gilroy, Bandura',sum:`<b>Propp:</b> character types (hero, villain, donor, helper, princess, dispatcher, false hero). <b>Baudrillard:</b> postmodernism, hyperreality and simulacra. <b>Gauntlett:</b> identity is fluid and media provide resources to build it. <b>van Zoonen:</b> feminist theory, gender is constructed by media. <b>Gilroy:</b> postcolonial theory, ethnicity and colonial legacy. <b>Bandura:</b> people imitate behaviour they see (social learning). Check which theorists your spec lists.`,q:[M(`Propp is known for...`,[`Character types such as hero and villain`,`Hyperreality`,`Binary oppositions`,`Cultivation`],`Propp identified recurring character roles in folk tales.`),M(`Baudrillard argued postmodern media...`,[`Create hyperreality where copies replace reality`,`Show reality accurately`,`Have no signs`,`Only affect children`],`Simulacra are copies with no original.`),M(`Bandura's theory suggests people...`,[`Learn behaviour by imitating role models`,`Ignore all media`,`Always oppose messages`,`Only copy adults in person`],`Social learning can include media role models.`),S_(`Explain Gauntlett's view of identity.`,[[`fluid`,`flexible`,`changing`,`construct`,`choose`],[`media`,`resources`,`role model`,`self`]],`Identity is fluid and self-constructed; media provide resources and role models people use to build it.`,2)]}]},{n:'Set products (your choices)',t:[{id:'m5',n:'Music videos: Titanium and Heaven',sum:`<b>Your videos:</b> Titanium (David Guetta ft. Sia) and Heaven (Emeli Sandé). <b>Apply:</b> Goodwin (link between lyrics, music and visuals, genre, star image), plus Barthes, Hall, Gilroy, Butler, van Zoonen. <b>Cover:</b> camerawork, editing, mise-en-scene, performance, representation, industries (labels, streaming). Paste your teacher notes and I will add specific shots and quotes.`,q:[M(`Titanium is a single by...`,[`David Guetta featuring Sia`,`Calvin Harris featuring Rihanna`,`Avicii featuring Aloe Blacc`,`Disclosure featuring Sam Smith`],`Released 2011.`),M(`Which theorist studied links between lyrics, music and visuals in music video?`,[`Goodwin`,`Todorov`,`Propp`,`Shirky`],`Andrew Goodwin: illustration, amplification, contradiction.`),M(`Heaven is performed by...`,[`Emeli Sandé`,`Adele`,`Sia`,`Rita Ora`],`Know the artist's star image and genre conventions.`),S_(`Analyse how one music video you studied uses media language to create meaning.`,[[`camera`,`shot`,`close-up`,`angle`],[`editing`,`cut`,`pace`,`transition`],[`mise`,`costume`,`setting`,`lighting`,`colour`,`location`],[`lyric`,`music`,`genre`,`star`,`performer`]],`Cover camerawork, editing, mise-en-scene and the link to lyrics, genre and star image, with named shots.`,3)]},{id:'m6',n:'Video games: Animal Crossing',sum:`<b>Animal Crossing: New Horizons</b> (Nintendo, 2020, Switch): life-simulation game with no fixed end. <b>Industry:</b> Nintendo makes console and games (vertical integration) and a family-friendly brand. <b>Audience:</b> broad, casual and social; lockdown boosted sales; players share islands online (Shirky, Jenkins). <b>Representation:</b> customisable avatars (Gauntlett). <b>Regulation:</b> PEGI. Add your own notes.`,q:[M(`Animal Crossing: New Horizons was published by...`,[`Nintendo`,`Sony`,`Microsoft`,`Electronic Arts`],`Released on the Nintendo Switch in 2020.`),M(`Which system gives age ratings to games sold in the UK?`,[`PEGI`,`ASA`,`IPSO`,`Ofcom`],`PEGI ratings guide parents and retailers.`),M(`Customising an avatar links best to which theorist?`,[`Gauntlett`,`Propp`,`Todorov`,`Curran and Seaton`],`Identity is constructed using media resources.`),S_(`Explain how Animal Crossing shows audience participation.`,[[`share`,`online`,`social media`,`community`,`fans`,`screenshots`],[`create`,`design`,`customis`,`user-generated`,`produce`],[`shirky`,`jenkins`,`participat`,`prosum`]],`Players design and customise islands and share them online, creating content and communities (Shirky: users as producers; Jenkins: participatory fan culture).`,2)]}]}]}];

const r2=x=>+x.toFixed(2),rn=a=>a[Math.random()*a.length|0],tp=id=>{let r;SB.forEach(s=>s.th.forEach(h=>h.t.forEach(t=>{if(t.id==id)r=t})));return r};
const GS=(L,P,xl,yl)=>`<svg viewBox='0 0 270 190' style='max-width:360px;width:100%'><path d='M32 8V160H260' fill='none' stroke='currentColor' stroke-width='2'/>${L.map(l=>`<line x1='${l[0]}' y1='${l[1]}' x2='${l[2]}' y2='${l[3]}' stroke='${l[4]}' stroke-width='3'/><text x='${l[2]+3}' y='${l[3]+4}' font-size='11' fill='${l[4]}'>${l[5]}</text>`).join('')}${P.map(p=>`<circle cx='${p[0]}' cy='${p[1]}' r='4' fill='currentColor'/>`).join('')}<text x='190' y='178' font-size='10' fill='currentColor'>${xl}</text><text x='4' y='12' font-size='10' fill='currentColor'>${yl}</text></svg>`;
const DSG=(s,d,xl,yl)=>GS([[40,140,200,30,'#dc2626',s],[40,40,200,140,'#2563eb',d+'1'],[70,40,230,140,'#22a85a',d+'2']],[[116,88],[131,78]],xl,yl);
const TAXG=GS([[40,140,200,30,'#dc2626','S1'],[40,120,200,10,'#f59e0b','S2 (tax)'],[40,40,200,140,'#2563eb','D']],[[116,88],[101,78]],'Quantity','Price');
const PEDG=GS([[110,25,150,150,'#2563eb','Inelastic'],[40,80,215,120,'#dc2626','Elastic']],[],'Quantity','Price');
function mk(ty,d){const O=(t,a,w,e)=>({...M(t,[a,...w],e,d),gen:1});
if(ty=='ped'){let p=rn([5,10,20,25]),m=rn([.4,.5,1.5,2,2.5,3]),y=r2(p*m);if(d=='e')return O(`Price rises ${p}% and quantity demanded falls ${y}%. What is PED?`,r2(-m),[r2(m),r2(-1/m),r2(-m-1)],`PED = ${-y} / ${p} = ${r2(-m)}`);if(d=='m'){let p0=rn([10,20,40]),q0=rn([100,200,500]);return O(`Price rises from £${p0} to £${r2(p0*(1+p/100))} and quantity demanded falls from ${q0} to ${r2(q0*(1-y/100))}. What is PED?`,r2(-m),[r2(-1/m),r2(m),r2(-m-1)],`%change in Q = -${y}%, %change in P = +${p}%, so PED = ${r2(-m)}`)}return O(`PED is ${r2(-m)}. Price rises ${p}%. What happens to quantity demanded?`,`Falls by ${y}%`,[`Rises by ${y}%`,`Falls by ${r2(p/m)}%`,`Falls by ${r2(y+p)}%`],`%change in Q = PED x %change in P = ${r2(-m)} x ${p} = -${y}%`)}
if(ty=='inf'){let o=d=='e'?100:rn([110,120,125,150,200]),pc=rn([2,3,4,5,8,10]),n=r2(o*(1+pc/100));if(d=='h'){let w=pc+rn([1,2,3,4]);return O(`Nominal wages rise ${w}% while inflation is ${pc}%. Real wages have...`,`Risen by about ${w-pc}%`,[`Fallen by about ${w-pc}%`,`Risen by about ${w+pc}%`,`Stayed the same`],`Real wage change is roughly nominal change minus inflation: ${w} - ${pc} = ${w-pc}%`)}return O(`The CPI rises from ${o} to ${n}. What is the inflation rate?`,`${pc}%`,[`${r2((n-o)/n*100)}%`,`${n}%`,`${pc+2}%`],`(${n} - ${o}) / ${o} x 100 = ${pc}%`)}
if(ty=='gdp'){let g=rn([200,400,500,1000,1500]),r=rn([1,2,2.5,3,4]);if(d=='h')return O(`Real GDP of £${g}bn grows ${r}% each year for 2 years. What is GDP after 2 years?`,`£${r2(g*(1+r/100)**2)}bn`,[`£${r2(g*(1+2*r/100))}bn`,`£${r2(g*(1+r/100))}bn`,`£${r2(g*(1+r/100)**3)}bn`],`Compound growth: ${g} x (1 + ${r}/100)^2`);return O(`Real GDP rises from £${g}bn to £${r2(g*(1+r/100))}bn. What is the growth rate?`,`${r}%`,[`${r2(r*2)}%`,`${r2(g*r/100)}%`,`${r2(r/2)}%`],`Growth = (new - old) / old x 100 = ${r}%`)}
if(ty=='mult'){let m=rn([.6,.75,.8,.9]),k=r2(1/(1-m)),j=rn([2,4,5,10,20]);if(d=='e')return O(`The MPC is ${m}. What is the multiplier?`,k,[r2(1/m),r2(m/(1-m)),r2(1-m)],`k = 1 / (1 - MPC) = 1 / ${r2(1-m)} = ${k}`);if(d=='m')return O(`The MPC is ${m} and investment rises by £${j}bn. What is the total rise in income?`,`£${r2(k*j)}bn`,[`£${j}bn`,`£${r2(j/m)}bn`,`£${r2(j*m)}bn`],`Multiplier ${k} x £${j}bn = £${r2(k*j)}bn`);let s=rn([.1,.2]),t=rn([.1,.15]),i=rn([.05,.1]),w=r2(s+t+i);return O(`Out of each extra £1, households save ${r2(s*100)}p, pay ${r2(t*100)}p in tax and spend ${r2(i*100)}p on imports. What is the multiplier?`,r2(1/w),[r2(1/s),r2(1/(1-w)),r2(w)],`Withdrawals = ${w}, so k = 1 / ${w} = ${r2(1/w)}`)}
if(ty=='prof'){let P=rn([2,4,5,8,10,12]),Q=rn([100,200,500,1000]),C=r2(P*Q*rn([.6,.75,1.2]));if(d=='e')return O(`A firm sells ${Q} units at £${P} each. What is total revenue?`,`£${P*Q}`,[`£${P+Q}`,`£${r2(Q/P)}`,`£${P*Q*2}`],`Total revenue = price x quantity = ${P} x ${Q} = £${P*Q}`);if(d=='m')return O(`Total revenue is £${P*Q} and total costs are £${C}. What is profit?`,`£${r2(P*Q-C)}`,[`£${r2(P*Q+C)}`,`£${r2(C-P*Q)}`,`£${P*Q}`],`Profit = TR - TC = ${P*Q} - ${C}`);return O(`A firm makes ${Q} units at total cost £${C} and sells each at £${P}. What is profit per unit?`,`£${r2(P-C/Q)}`,[`£${r2(P+C/Q)}`,`£${r2(C/Q)}`,`£${r2(P*Q-C)}`],`Average cost = ${C} / ${Q} = £${r2(C/Q)}; profit per unit = ${P} - ${r2(C/Q)}`)}}
function pad(){let c=$('cv'),x=c.getContext('2d'),d=0,er=0,ax=()=>{x.fillStyle='#fff';x.fillRect(0,0,600,420);x.strokeStyle='#c4c4d0';x.lineWidth=3;x.beginPath();x.moveTo(60,20);x.lineTo(60,380);x.lineTo(570,380);x.stroke()},p=e=>{let r=c.getBoundingClientRect();return[(e.clientX-r.left)*600/r.width,(e.clientY-r.top)*420/r.height]},st=()=>{x.strokeStyle=er?'#fff':'#111';x.lineWidth=er?26:3};ax();x.lineCap='round';x.lineJoin='round';c.onpointerdown=e=>{d=1;c.setPointerCapture(e.pointerId);let[a,b]=p(e);st();x.beginPath();x.moveTo(a,b);x.lineTo(a+.1,b);x.stroke();x.beginPath();x.moveTo(a,b);e.preventDefault()};c.onpointermove=e=>{if(!d)return;let[a,b]=p(e);st();x.lineTo(a,b);x.stroke();x.beginPath();x.moveTo(a,b)};c.onpointerup=c.onpointercancel=()=>d=0;window.tool=t=>er=t;window.clr=ax}
function gmark(){let q=QM[S.ids[S.i]],t=[...document.querySelectorAll('.ck')],n=t.filter(x=>x.checked).length,ok=n>=Math.ceil(t.length*.7),last=S.i==S.ids.length-1;rec(q,ok);$('fb').innerHTML=`<h3 class='${ok?'ok':'no'}'>${ok?'✅':'❌'} ${n}/${t.length} marks${ok?' · ⚡ +'+LP+' pts':''}</h3><p class='sm'>Self-marked against the mark scheme. 70% or more counts as correct.</p><button class='btn' onclick='next()'>${last?'See results':'Next question'}</button>`}
const dch=()=>`<div style='margin:8px 0'><span class='sm'>Difficulty:</span><br>${[['a','Mixed'],['e','Easy'],['m','Medium'],['h','Hard']].map(([k,l])=>`<button class='ln' style='${DIF==k?'background:var(--p);color:#fff':''}' onclick="DIF='${k}';render()">${l}</button>`).join('')}<br><button class='ln' style='${TMR?'background:var(--p);color:#fff':''}' onclick='TMR=!TMR;render()'>⏱ Timed: ${TMR?'On':'Off'}</button></div>`;
SB[1].th[0].soon='1.1 Nature of economics, 1.3 Market failure, 1.4 Government intervention';SB[1].th[1].soon='2.1 Measures of performance, 2.4 National income, 2.5 Growth, 2.6 Macro policies';SB[1].th[2].soon='3.1 Business growth, 3.2 Objectives, 3.3 Revenue and costs, 3.5 Labour market, 3.6 Intervention';SB[1].th[3].soon='4.2 Poverty and inequality, 4.3 Developing economies, 4.4 Financial sector, 4.5 Role of the state';
tp('e1').gen=['ped'];tp('e1').sum=`<h4>Definition</h4><p><b>Price elasticity of demand (PED)</b> measures how much the quantity demanded changes when price changes.</p><p class='f'>PED = %change in quantity demanded ÷ %change in price</p><h4>How to read it</h4><ul><li><b>Elastic</b> (more than 1, ignoring the minus sign): buyers react a lot, e.g. restaurant meals or branded snacks.</li><li><b>Inelastic</b> (less than 1): buyers barely react, e.g. petrol, cigarettes, insulin.</li><li><b>Unit elastic</b> = 1, <b>perfectly inelastic</b> = 0, <b>perfectly elastic</b> = infinity.</li></ul><h4>What affects PED?</h4><ul><li><b>Substitutes:</b> more close substitutes means more elastic (Coke vs Pepsi).</li><li><b>Necessity vs luxury:</b> necessities are inelastic.</li><li><b>Share of income:</b> a pack of salt is inelastic, a new car is elastic.</li><li><b>Time:</b> more elastic in the long run (people eventually switch to electric cars).</li><li><b>Addiction or habit:</b> makes demand inelastic.</li></ul><h4>Why firms and governments care</h4><p>If demand is <b>elastic</b>, a price cut raises revenue. If <b>inelastic</b>, a price rise raises revenue (train companies charge more at peak times). Governments tax petrol and cigarettes heavily because demand is inelastic, so tax revenue stays high.</p>${PEDG}<p class='sm'>Steep curve = inelastic. Flat curve = elastic.</p><h4>Related ideas</h4><p><b>YED</b> (income elasticity) is positive for normal goods and negative for inferior goods. <b>XED</b> (cross elasticity) is positive for substitutes and negative for complements.</p><h4>Evaluation</h4><p>PED changes along a demand curve, depends on the time period, and is only an estimate, so firms cannot rely on it perfectly.</p>`;
tp('e1').q.push(M(`Demand with a PED of 0.2 is...`,[`Price inelastic`,`Price elastic`,`Unit elastic`,`Perfectly elastic`],`Below 1 means quantity barely responds.`,'e'),M(`Why do governments heavily tax cigarettes?`,[`Demand is inelastic so revenue stays high`,`Demand is elastic so consumption falls a lot`,`They have many substitutes`,`PED is greater than 1`],`Inelastic demand means a tax raises revenue without cutting sales much.`,'m'),M(`Which firm should consider cutting its price to raise revenue?`,[`One whose demand is price elastic`,`One whose demand is price inelastic`,`A monopoly with PED of 0`,`One selling a necessity`],`If demand is elastic, quantity rises proportionately more than price falls.`,'m'),M(`Why is demand usually more elastic in the long run?`,[`Consumers have time to find substitutes`,`Prices fall over time`,`Incomes always rise`,`Firms advertise more`],`E.g. drivers can eventually switch to electric cars if petrol rises.`,'h'),S_(`Evaluate whether a firm should raise prices if its demand is inelastic.`,[[`revenue`,`rise`,`increase`],[`inelastic`,`ped`],[`long run`,`substitute`,`competitor`,`brand`,`loyal`,`profit`,`cost`]],`Revenue rises as quantity falls proportionately less. But the long run may bring more elastic demand, rivals and substitutes, and profit also depends on costs.`,2,'h'),GQ(`Sketch a price elastic and a price inelastic demand curve on the same axes and label them.`,[`Axes labelled Price and Quantity`,`A steep downward-sloping curve labelled inelastic`,`A flatter downward-sloping curve labelled elastic`,`Both curves clearly different in steepness`],PEDG,'e'));
tp('e2').gen=['inf','gdp'];tp('e2').sum=`<h4>Definition</h4><p><b>Inflation</b> is a sustained rise in the general price level, so each £1 buys less. The UK target is 2% CPI (Consumer Price Index). <b>Deflation</b> = falling prices. <b>Disinflation</b> = inflation slowing but still positive.</p><p class='f'>Inflation % = (new index − old index) ÷ old index × 100</p><h4>Causes</h4><ul><li><b>Demand-pull:</b> AD grows faster than the economy can supply (e.g. a spending boom after lockdowns).</li><li><b>Cost-push:</b> higher costs shift SRAS left (e.g. energy or raw material price spikes).</li><li><b>Imported inflation:</b> a weaker pound makes imports dearer. Also wage-price spirals and growth in the money supply.</li></ul><h4>Costs of inflation</h4><ul><li><b>Menu costs</b> (changing prices), <b>shoe-leather costs</b> (shopping around), the real value of savings falls, uncertainty hurts investment, exports become less competitive.</li></ul><h4>Controlling it</h4><ul><li><b>Monetary policy:</b> the Bank of England raises interest rates.</li><li><b>Fiscal policy:</b> higher taxes or lower government spending.</li><li><b>Supply-side policy:</b> raise productivity so SRAS shifts right.</li></ul>${DSG('SRAS','AD','Real GDP','Price level')}<p class='sm'>Demand-pull: AD shifts right (AD1 to AD2) and the price level rises.</p><h4>Evaluation</h4><p>Higher interest rates work with a time lag, hurt borrowers and growth, and do little against cost-push inflation.</p>`;
tp('e2').q.push(M(`If inflation is 3% and your wages rise 5%, your real wage has...`,[`Risen`,`Fallen`,`Stayed the same`,`Doubled`],`Real wages rise when pay grows faster than prices.`,'e'),M(`Which group often loses most from unexpected inflation?`,[`Savers with fixed-interest savings`,`Borrowers with fixed-rate debt`,`Owners of property`,`Governments with debt`],`The real value of savings falls, while debts shrink in real terms.`,'m'),M(`Which is a fiscal policy to reduce demand-pull inflation?`,[`Raising income tax`,`Raising interest rates`,`Quantitative easing`,`Devaluing the currency`],`Fiscal policy uses tax and spending; interest rates are monetary policy.`,'h'),S_(`Evaluate the use of higher interest rates to reduce inflation.`,[[`borrowing`,`spending`,`demand`],[`time lag`,`lag`,`delay`],[`cost-push`,`supply`,`unemployment`,`growth`,`exchange rate`]],`Higher rates cut borrowing and spending so AD falls, but there are time lags, they hurt growth and borrowers, and do little against cost-push inflation.`,2,'h'));
tp('e3').gen=['prof'];tp('e3').sum=`<h4>Key idea</h4><p>Market structure describes how competitive a market is: the number of firms, barriers to entry, and how much control firms have over price.</p><h4>The main types</h4><ul><li><b>Perfect competition:</b> many firms, identical products, free entry, <b>price takers</b> (e.g. farm produce).</li><li><b>Monopolistic competition:</b> many firms, differentiated products (hairdressers, cafes).</li><li><b>Oligopoly:</b> a few big firms, <b>interdependent</b> (UK supermarkets, energy suppliers). May collude (a <b>cartel</b>, which is illegal) or fight price wars.</li><li><b>Monopoly:</b> one dominant firm (25%+ share in the UK), high <b>barriers to entry</b>, a <b>price maker</b> (e.g. Google in search).</li></ul><h4>Profit maximisation</h4><p class='f'>Profit is maximised where MC = MR</p><p>Producing more adds to profit while extra revenue (MR) is above extra cost (MC).</p><h4>Is monopoly bad?</h4><p><b>Against:</b> higher prices, less output, less choice, x-inefficiency. <b>For:</b> economies of scale, supernormal profit funds R&amp;D, <b>natural monopolies</b> like water networks make sense. The CMA regulates abuse.</p><h4>Contestable markets</h4><p>If barriers and sunk costs are low, the threat of new entrants (like budget airlines) keeps prices down even with few firms.</p>`;
tp('e3').q.push(M(`A price taker is a firm that...`,[`Must accept the market price`,`Sets its own price freely`,`Has no competitors at all`,`Is publicly owned`],`Typical of perfect competition.`,'e'),M(`Which is a barrier to entry?`,[`High start-up costs`,`Many substitutes`,`Low sunk costs`,`Free information`],`Costs, patents and brand loyalty protect incumbent firms.`,'m'),M(`A cartel is an example of...`,[`Collusion in an oligopoly`,`Perfect competition`,`A natural monopoly`,`A contestable market`],`Firms agree prices or output; it is illegal in the UK.`,'h'));
tp('e4').sum=`<h4>Exchange rates</h4><p>An <b>exchange rate</b> is the price of one currency in terms of another (e.g. £1 = $1.30). Most major currencies <b>float</b>, set by supply and demand.</p><ul><li><b>Appreciation:</b> the currency rises. Exports become dearer, imports cheaper, inflation pressure falls.</li><li><b>Depreciation:</b> the currency falls. Exports cheaper, imports dearer, which can raise inflation. The pound fell sharply after the 2016 Brexit vote.</li><li><b>Causes:</b> interest rates (higher rates attract money), inflation, speculation, trade performance.</li></ul><h4>Trade</h4><p><b>Comparative advantage:</b> a country should specialise in what it gives up least to produce (lowest <b>opportunity cost</b>), then trade. Benefits: lower prices, more choice, economies of scale.</p><p><b>Protectionism:</b> <b>tariffs</b> (taxes on imports), <b>quotas</b>, <b>subsidies</b>. Used to protect infant industries and jobs, but they raise prices and invite retaliation (trade wars).</p><h4>Balance of payments</h4><p>The <b>current account</b> covers trade in goods and services, income and transfers. A <b>deficit</b> means more money flows out than in.</p><h4>Evaluation</h4><p>A depreciation only helps the trade balance if demand for exports and imports is elastic enough (the Marshall-Lerner condition).</p>`;
tp('e4').q.push(M(`If £1 = $1.30 rises to £1 = $1.50 the pound has...`,[`Appreciated`,`Depreciated`,`Devalued`,`Stayed the same`],`More dollars per pound means a stronger pound.`,'e'),M(`Which is a benefit of free trade?`,[`Consumers get more choice and lower prices`,`Higher tariffs`,`Less competition`,`Fewer exports`],`Specialisation and competition lower prices.`,'e'),M(`A current account deficit means...`,[`The country imports more than it exports`,`It exports more than it imports`,`The government has a budget deficit`,`Its currency is fixed`],`Outflows exceed inflows on the current account.`,'m'),M(`Which would most likely reduce a trade deficit?`,[`A depreciation of the currency`,`An appreciation of the currency`,`A cut in export subsidies`,`A rise in imports`],`Cheaper exports and dearer imports, if demand is elastic enough.`,'h'));
SB[1].th[0].t.push({id:'e6',n:'How markets work: supply and demand',gen:[],sum:`<h4>The big idea</h4><p>A <b>market</b> is where buyers and sellers meet. Price adjusts until the amount people want to buy equals the amount firms want to sell. That is <b>equilibrium</b>.</p><h4>Key terms</h4><ul><li><b>Demand:</b> what people are willing and able to buy at each price.</li><li><b>Supply:</b> what firms are willing and able to sell at each price.</li><li><b>Excess demand</b> (shortage): price below equilibrium. <b>Excess supply</b> (surplus): price above.</li><li><b>Ceteris paribus:</b> everything else held constant.</li></ul><h4>Movement vs shift</h4><p>A change in the good's own <b>price</b> causes a <b>movement along</b> the curve. Anything else <b>shifts</b> it.</p><p><b>Demand shifters (PIRATES):</b> Population, Income, Related goods (substitutes and complements), Advertising, Tastes, Expectations, Seasons.</p><p><b>Supply shifters:</b> costs of production, technology, taxes and subsidies, weather, number of firms.</p><h4>Real-world examples</h4><p>A heatwave raises demand for ice cream (shift right): price and quantity rise. A bad harvest cuts the supply of wheat (shift left): price rises, quantity falls.</p>${DSG('S','D','Quantity','Price')}<p class='sm'>Demand shifts right (D1 to D2): equilibrium price and quantity both rise.</p><h4>Taxes</h4><p>An indirect tax raises costs and shifts supply left (up). Consumers pay more, producers receive less.</p>${TAXG}<h4>Evaluation</h4><p>Real markets have imperfect information, irrational buyers and market failure, so the model is a simplification.</p>`,q:[M(`Which causes a movement along the demand curve?`,[`A change in the good's own price`,`A rise in incomes`,`A change in tastes`,`A fall in the price of a substitute`],`Only a change in price moves you along the curve.`,'e'),M(`At a price above equilibrium there is...`,[`Excess supply`,`Excess demand`,`Equilibrium`,`A shortage`],`Firms supply more than buyers want, so price tends to fall.`,'e'),M(`A rise in the price of a substitute will...`,[`Shift demand for the good right`,`Shift demand left`,`Shift supply right`,`Move down the demand curve`],`Buyers switch towards the cheaper good.`,'m'),M(`Which would shift the supply of coffee left?`,[`Frost destroying crops`,`Cheaper fertiliser`,`Better technology`,`A subsidy to growers`],`Higher costs or lower output shift supply left.`,'m'),M(`With inelastic demand, an indirect tax on a good will mean consumers pay...`,[`More of the tax`,`Less of the tax`,`None of the tax`,`The tax is cancelled`],`Inelastic buyers cannot switch, so more of the tax falls on them.`,'h'),S_(`Explain why a heatwave raises the equilibrium price of ice cream.`,[[`demand`,`shift right`,`increase in demand`],[`excess demand`,`shortage`,`bid up`,`price rises`],[`equilibrium`,`new`,`quantity`]],`The heatwave raises demand (shift right), creating excess demand at the old price, so price rises to a new equilibrium.`,2,'h'),GQ(`Draw a supply and demand diagram showing a rise in incomes for a normal good. Label axes, curves and equilibria.`,[`Axes labelled Price and Quantity`,`Downward demand curve and upward supply curve`,`Demand shifts right to D2`,`Old and new equilibrium shown`,`Price and quantity both rise`],DSG('S','D','Quantity','Price'),'m'),GQ(`Draw a diagram showing the effect of an indirect tax on a market.`,[`Axes labelled Price and Quantity`,`Original S and D curves`,`Supply shifts left or up to S2`,`New equilibrium with higher price and lower quantity`],TAXG,'h')]});
SB[1].th[1].t.push({id:'e5',n:'Aggregate demand and aggregate supply',gen:['mult','gdp'],sum:`<h4>Aggregate demand (AD)</h4><p>Total demand for UK goods and services at each price level.</p><p class='f'>AD = C + I + G + (X − M)</p><ul><li><b>C</b> household spending, <b>I</b> investment by firms, <b>G</b> government spending, <b>X − M</b> net exports.</li><li>AD shifts right with lower interest rates, higher confidence, tax cuts or a weaker pound.</li></ul><h4>Aggregate supply (AS)</h4><ul><li><b>SRAS:</b> shifts with costs (wages, energy, raw materials).</li><li><b>LRAS:</b> the economy's productive capacity. Shifts right with better skills, technology and investment.</li></ul><h4>Real-world examples</h4><p>The 2022 energy price jump shifted SRAS left (cost-push). Furlough support in the pandemic supported AD.</p>${DSG('SRAS','AD','Real GDP','Price level')}<p class='sm'>AD shifts right: real GDP and the price level both rise.</p><h4>The multiplier</h4><p class='f'>Multiplier k = 1 ÷ (1 − MPC) = 1 ÷ MPW</p><p>An initial injection leads to a bigger final rise in income because spending is re-spent. <b>MPC</b> = share of extra income spent; <b>MPW</b> = share withdrawn (saving, tax, imports).</p><h4>Evaluation</h4><p>Effects depend on spare capacity: with spare capacity AD mainly raises output; near full capacity it mainly raises prices.</p>`,q:[M(`Which is a component of aggregate demand?`,[`Investment`,`Savings`,`Taxes`,`Wages`],`AD = C + I + G + (X - M).`,'e'),M(`AD = C + I + G + ...`,[`(X - M)`,`(M - X)`,`T`,`S`],`Net exports are exports minus imports.`,'e'),M(`A rise in interest rates is most likely to shift...`,[`AD left`,`AD right`,`SRAS right`,`LRAS right`],`Higher rates cut borrowing and spending.`,'m'),M(`Which would shift SRAS to the right?`,[`A fall in oil prices`,`A rise in wages`,`Higher VAT`,`A rise in raw material costs`],`Lower costs of production raise short-run supply.`,'m'),M(`Which would shift LRAS to the right?`,[`Better education and skills`,`A cut in interest rates`,`Higher government spending`,`Rising consumer confidence`],`LRAS depends on productive capacity.`,'h'),S_(`Explain how higher government spending could raise real GDP.`,[[`aggregate demand`,`demand`],[`multiplier`,`income`,`jobs`,`employment`,`spending`],[`real gdp`,`output`,`growth`]],`Government spending is part of AD so AD shifts right; the multiplier raises incomes and spending further, so output and real GDP rise.`,2,'m'),GQ(`Draw an AD/AS diagram showing demand-pull inflation.`,[`Axes labelled Price level and Real GDP`,`Downward AD and upward SRAS`,`AD shifts right to AD2`,`Price level and real GDP both rise`],DSG('SRAS','AD','Real GDP','Price level'),'h')]});
tp('rs1').q.push(M(`Which argument starts from the idea that the universe needs a first cause?`,[`Cosmological`,`Ontological`,`Moral`,`Teleological`],`Aquinas argued for an uncaused first cause.`,'e'),S_(`Evaluate Anselm's ontological argument. [12 marks] Explain the argument, give a criticism (e.g. Gaunilo or Kant), and reach a judgement on whether it succeeds.`,[[`greater than`,`conceived`,`perfect`,`necessary existence`],[`gaunilo`,`island`],[`kant`,`predicate`,`existence`],[`a priori`,`only if you accept`,`believer`]],`Anselm: God is that than which nothing greater can be conceived, so must exist. Gaunilo's perfect island and Kant's point that existence is not a predicate challenge it. As an a priori argument it may only convince believers.`,3,'h'));
tp('rs2').q.push(M(`Which describes act utilitarianism?`,[`Judging each action by its consequences for happiness`,`Following fixed moral rules`,`Obeying divine commands`,`Acting from duty`],`Each act is judged by the happiness it produces.`,'e'),S_(`Evaluate whether utilitarianism is a good guide to moral decisions. [12 marks] Explain its key ideas, give strengths and criticisms, and reach a judgement.`,[[`consequence`,`happiness`,`pleasure`,`utility`],[`minority`,`rights`,`justice`],[`predict`,`calculate`,`hedonic`],[`rule`,`mill`,`higher`,`quality`]],`Strengths: simple, focuses on consequences and happiness. Weaknesses: can ignore minority rights and justice, consequences are hard to predict and calculate. Mill and rule utilitarianism offer partial answers.`,3,'h'));
tp('rs3').q.push(M(`Natural evil is...`,[`Suffering caused by nature, such as earthquakes`,`Suffering caused by human choices`,`A punishment for sin only`,`An illusion`],`Moral evil comes from human actions; natural evil does not.`,'e'),S_(`Evaluate whether the problem of evil proves that God does not exist. [12 marks] Explain the problem, assess at least one theodicy, and reach a judgement.`,[[`omnipotent`,`omnibenevolent`,`inconsistent`,`mackie`],[`free will`,`augustine`,`irenaeus`,`soul-making`,`hick`],[`natural evil`,`moral evil`,`scale`,`evidential`],[`logical`,`not proved`,`theodicy`,`faith`]],`Mackie's inconsistent triad suggests God cannot be all-powerful and all-good. Theodicies (Augustine's free will, Hick's soul-making) respond, but the scale of natural evil remains hard to explain. It challenges rather than disproves.`,3,'h'));
tp('rs4').q.push(M(`A conversion experience is...`,[`A life-changing religious experience`,`A type of miracle`,`A philosophical argument`,`A moral rule`],`It changes someone's beliefs or way of life.`,'e'),S_(`Evaluate whether religious experience is good evidence for God. [12 marks] Explain what supporters argue, give challenges, and reach a judgement.`,[[`swinburne`,`credulity`,`testimony`],[`james`,`mystical`,`noetic`,`ineffable`],[`freud`,`persinger`,`brain`,`delusion`],[`subjective`,`verify`,`hume`,`other religions`]],`Swinburne: trust experience unless there is reason not to. James: mystical experiences feel authoritative. But Freud and Persinger offer natural explanations and experiences are subjective and hard to verify.`,3,'h'));
tp('rs5').q.push(M(`Via negativa describes God by...`,[`Saying what God is not`,`Using analogy`,`Using symbols only`,`Using scientific language`],`It avoids positive claims that limit God.`,'e'),S_(`Evaluate whether religious language is meaningless. [12 marks] Explain the challenge (e.g. verification or falsification), assess a response, and reach a judgement.`,[[`ayer`,`verification`,`verifiable`,`vienna`],[`flew`,`falsification`,`gardener`,`hare`,`blik`],[`wittgenstein`,`language game`,`community`],[`aquinas`,`analogy`,`tillich`,`symbol`,`via negativa`]],`Ayer and Flew say religious claims cannot be verified or falsified. Wittgenstein says meaning comes from use in a community; Aquinas and Tillich offer analogy and symbol.`,3,'h'));
tp('rs6').q.push(M(`Which view says miracles are possible if there is good evidence?`,[`Swinburne`,`Hume`,`Holland`,`Wiles`],`Swinburne argues evidence could make a miracle credible.`,'m'),S_(`Evaluate Hume's view that belief in miracles is never rational. [12 marks] Explain his arguments, assess criticisms, and reach a judgement.`,[[`hume`,`law of nature`,`violation`,`uniform`],[`testimony`,`witness`,`unreliable`],[`swinburne`,`evidence`,`possible`,`probab`],[`holland`,`wiles`,`coincidence`,`religious significance`]],`Hume: miracles violate laws of nature and testimony is less reliable than uniform experience. Swinburne replies that evidence could still support a miracle; Holland and Wiles redefine miracles.`,3,'h'));
tp('rs7').q.push(M(`Natural Law says moral rules come from...`,[`Human purpose and reason`,`Pleasure and pain`,`Individual feelings`,`Cultural custom`],`Aquinas: reason works out right from our God-given purpose.`,'e'),S_(`Evaluate Natural Law as an approach to ethics. [12 marks] Explain its key ideas, assess strengths and weaknesses, and reach a judgement.`,[[`aquinas`,`telos`,`purpose`,`reason`],[`primary precept`,`secondary`,`double effect`],[`hume`,`ought`,`rigid`,`absolute`],[`universal`,`strength`,`objective`]],`Strengths: universal and objective, based on reason. Weaknesses: assumes a fixed purpose, rigid on issues like contraception, and Hume says you cannot derive ought from is.`,3,'h'));
tp('b1').q.push(M(`Nirvana means...`,[`Ending the fires of greed, hatred and ignorance`,`Rebirth in heaven`,`Worship of the Buddha`,`A sacred text`],`It ends craving and the cycle of rebirth.`,'e'),S_(`Explain the three marks of existence. [6 marks] Name each mark and say what it means.`,[[`anicca`,`impermanen`],[`dukkha`,`suffering`,`unsatisf`],[`anatta`,`no self`,`no fixed self`]],`Anicca: everything changes. Dukkha: life involves suffering or dissatisfaction. Anatta: there is no permanent self.`,3,'m'));
tp('e1').q.push(M(`If PED = 0, demand is...`,[`Perfectly inelastic`,`Perfectly elastic`,`Unit elastic`,`Elastic`],`Quantity does not respond at all to price.`,'e'),S_(`Analyse how a firm could use PED when setting prices. [6 marks] Use a chain of reasoning: price change, effect on quantity, effect on revenue.`,[[`elastic`,`inelastic`],[`revenue`,`total revenue`],[`price rise`,`price cut`,`lower price`,`raise price`],[`quantity`,`demand`]],`If demand is elastic a price cut raises revenue as quantity rises proportionately more; if inelastic a price rise raises revenue as quantity falls proportionately less.`,3,'h'));
tp('e2').q.push(M(`Which is a cost of inflation to firms?`,[`Menu costs`,`Higher real wages`,`Cheaper imports`,`Lower interest rates`],`Menu costs are the costs of changing prices.`,'e'),S_(`Evaluate the effects of inflation on UK households. [12 marks] Analyse the effects on savers, borrowers and wage earners, then judge how serious they are.`,[[`savers`,`savings`,`real value`],[`borrowers`,`debt`],[`wages`,`real income`,`pensioners`,`fixed income`],[`depends`,`unexpected`,`rate of inflation`,`low`]],`Savers and people on fixed incomes lose; borrowers gain as debts shrink. Real wages depend on pay compared with prices. Effects depend on how high and how expected inflation is.`,3,'h'));
tp('e3').q.push(M(`Which market structure has the most firms?`,[`Perfect competition`,`Monopoly`,`Oligopoly`,`Duopoly`],`Perfect competition has many small firms.`,'e'),S_(`Evaluate the likely effects of a monopoly on consumers. [12 marks] Analyse costs and benefits for consumers, then reach a judgement.`,[[`price`,`higher price`],[`output`,`choice`,`quality`],[`economies of scale`,`innovation`,`r&d`],[`regulat`,`cma`,`depends`]],`Likely higher prices, lower output and less choice. But economies of scale and supernormal profit funding R&D can benefit consumers. Regulation by the CMA matters.`,3,'h'));
tp('e4').q.push(M(`A quota is...`,[`A limit on the quantity of imports`,`A tax on imports`,`A subsidy to exporters`,`A tax on exports`],`Quotas cap how much can be imported.`,'e'),S_(`Evaluate the case for protectionism. [12 marks] Analyse reasons for and against, then reach a judgement.`,[[`infant industr`,`jobs`,`protect`],[`tariff`,`quota`,`subsid`],[`retaliat`,`trade war`,`higher price`,`inefficien`],[`comparative advantage`,`consumer`,`free trade`]],`Protects infant industries and jobs, but raises prices, invites retaliation and reduces the gains from comparative advantage and free trade.`,3,'h'));
tp('e5').q.push(M(`The multiplier effect means...`,[`An initial injection leads to a larger rise in income`,`Prices multiply each year`,`Exports always rise`,`Taxes fall automatically`],`Spending is re-spent, so the final rise is larger.`,'e'),S_(`Evaluate the effectiveness of fiscal policy in raising economic growth. [12 marks] Explain how it works, analyse its limits, and reach a judgement.`,[[`government spending`,`tax cut`,`aggregate demand`],[`multiplier`,`crowding out`,`borrowing`,`debt`],[`time lag`,`spare capacity`,`depends`],[`supply-side`,`long run`,`inflation`]],`Spending and tax cuts raise AD and the multiplier boosts growth. But borrowing, crowding out, time lags and little spare capacity limit it; supply-side policy helps the long run.`,3,'h'));
tp('e6').q.push(M(`The price of a complement falls. Demand for the other good will...`,[`Rise`,`Fall`,`Stay the same`,`Become inelastic`],`E.g. cheaper printers raise demand for ink.`,'m'),S_(`Analyse how a rise in the cost of production affects a market. [6 marks] Use a chain of reasoning: supply shift, then price and quantity.`,[[`supply`,`shift left`,`decrease`],[`price`,`rise`,`higher price`],[`quantity`,`fall`,`demand`],[`equilibrium`,`new`]],`Higher costs shift supply left, creating excess demand at the old price, so the equilibrium price rises and quantity falls.`,3,'h'));
tp('m1').q.push(M(`Which theorist is linked to the five-stage narrative structure?`,[`Todorov`,`Propp`,`Barthes`,`Neale`],`Equilibrium, disruption, recognition, repair, new equilibrium.`,'e'),S_(`Analyse how a media product uses semiotics to create meaning. [6 marks] Use denotation and connotation with examples of signs.`,[[`denotation`,`denote`],[`connotation`,`connote`],[`sign`,`signifier`,`signified`,`barthes`],[`colour`,`font`,`image`,`mise-en-scene`,`costume`]],`Denotation is what is shown; connotation is the associated meaning, built from signs such as colour, image, font and costume (Barthes).`,3,'h'));
tp('m2').q.push(M(`Which theorist is linked to preferred, negotiated and oppositional readings?`,[`Hall`,`Gerbner`,`Shirky`,`Butler`],`Hall's reception theory.`,'e'),S_(`Evaluate the extent to which media representations reinforce stereotypes. [12 marks] Explain the theory, give examples for and against, and reach a judgement.`,[[`stereotype`,`simplif`],[`hall`,`construct`,`represent`],[`gender`,`butler`,`ethnic`,`gilroy`,`age`],[`challenge`,`subvert`,`audience`,`negotiated`]],`Representations are constructed (Hall) and often simplify groups, reinforcing stereotypes. But some products challenge them, and audiences can negotiate or oppose meanings.`,3,'h'));
tp('m3').q.push(M(`Which body regulates broadcast television in the UK?`,[`Ofcom`,`PEGI`,`IPSO`,`The Premier League`],`Ofcom regulates TV and radio.`,'e'),S_(`Evaluate the impact of media ownership on the content audiences receive. [12 marks] Explain ownership concepts, assess effects and counter-arguments, and reach a judgement.`,[[`curran`,`seaton`,`conglomerate`,`ownership`],[`vertical`,`horizontal`,`integration`],[`regulat`,`ofcom`,`public service`],[`digital`,`online`,`diversity`,`power`]],`Curran and Seaton: a few conglomerates hold power over content. Integration concentrates ownership, but regulation, public service media and online platforms add diversity.`,3,'h'));
tp('m4').q.push(M(`Which theorist is linked to hyperreality?`,[`Baudrillard`,`Propp`,`Gilroy`,`Bandura`],`Baudrillard: simulacra and hyperreality.`,'e'),S_(`Explain how one theory of identity can be applied to media. [6 marks] Name the theory, explain it, and apply it to an example.`,[[`gauntlett`,`identity`,`butler`,`gilroy`],[`construct`,`fluid`,`performed`,`postcolonial`],[`media`,`role model`,`represent`,`audience`]],`Gauntlett: identity is fluid and media provide role models and resources audiences use to build identity.`,2,'m'));
tp('m5').q.push(M(`Goodwin's music video theory focuses on...`,[`The link between lyrics, music and visuals`,`Cultivation of fear`,`Media ownership`,`Binary oppositions`],`Illustration, amplification and contradiction.`,'e'),S_(`Analyse how representation is constructed in a music video you have studied. [6 marks] Use named shots or techniques and link to a theory.`,[[`represent`,`construct`],[`camera`,`costume`,`setting`,`editing`,`performance`],[`artist`,`star`,`gender`,`ethnic`,`identity`],[`hall`,`butler`,`gilroy`,`van zoonen`]],`Use named shots: camerawork, costume, setting, editing and performance construct representations of the artist and identity, linked to a theorist such as Hall or Butler.`,3,'h'));
tp('m6').q.push(M(`Participatory culture means...`,[`Fans actively create and share content`,`Audiences are passive`,`Only studios make media`,`Media is state controlled`],`Jenkins and Shirky describe active audiences.`,'e'),S_(`Analyse how video games differ from traditional media for audiences. [6 marks] Compare interactivity, participation and the audience's role.`,[[`interactive`,`interact`,`player`,`control`],[`participat`,`social`,`online`,`community`],[`shirky`,`jenkins`,`user-generated`],[`narrative`,`immersive`,`choice`]],`Games are interactive: players control the outcome, take part socially online and create content, unlike passive viewing (Shirky, Jenkins).`,3,'h'));
const genTot=d=>{let[x,m]=rn([[120,100],[100,125],[150,120],[90,120],[110,100],[130,104]]),a=r2(x/m*100);return {...M(`The export price index is ${x} and the import price index is ${m}. What are the terms of trade?`,[a,r2(m/x*100),r2(x-m),r2(x+m)],`ToT = ${x} / ${m} x 100 = ${a}`,d),gen:1}};const _mk=mk;mk=(ty,d)=>ty=='tot'?genTot(d):_mk(ty,d);
SB[1].th[3].t.push({id:'e7',n:'Terms of trade',gen:['tot'],sum:`<h4>Definition</h4><p><b>Terms of trade (ToT)</b> compare the prices a country gets for its exports with the prices it pays for imports.</p><p class='f'>ToT = (index of export prices ÷ index of import prices) × 100</p><h4>Reading it</h4><ul><li>ToT <b>rises</b> (improves): each unit of exports buys <b>more</b> imports.</li><li>ToT <b>falls</b> (deteriorates): each unit of exports buys <b>fewer</b> imports.</li></ul><h4>Causes</h4><ul><li>Changes in export or import prices, such as commodity price swings.</li><li>The exchange rate: an appreciation makes imports cheaper in the home currency and can improve ToT.</li><li>Inflation, productivity and demand for exports and imports.</li></ul><h4>Real-world example</h4><p>A country that mainly exports a raw material such as copper or oil sees its ToT rise when world prices boom and fall when they crash. Developing economies that rely on a few primary products are often hit hardest (the Prebisch-Singer view is that primary product prices tend to fall relative to manufactured goods over time).</p><h4>Evaluation</h4><p>A better ToT does not always mean a better economy: it says nothing about the <b>volume</b> of trade or competitiveness. If exports become dearer, demand for them could fall. The index also uses averages that hide differences between goods.</p>`,q:[M(`If export prices rise while import prices stay the same, the terms of trade...`,[`Improve`,`Deteriorate`,`Stay the same`,`Fall to zero`],`Each unit of exports now buys more imports.`,'e'),M(`If a country's terms of trade improve, each unit of exports can buy...`,[`More imports`,`Fewer imports`,`The same imports`,`Only domestic goods`],`ToT compares export prices with import prices.`,'m'),M(`Why might a country dependent on primary products suffer from volatile terms of trade?`,[`Commodity prices fluctuate sharply`,`Manufactured goods prices never change`,`Exchange rates are fixed`,`Imports are always cheap`],`Reliance on a few commodities exposes export income to price swings.`,'h'),S_(`Evaluate whether an improvement in the terms of trade is always good for an economy. [12 marks] Explain what terms of trade means, analyse benefits and drawbacks, and reach a judgement.`,[[`export`,`import`,`price`],[`volume`,`demand`,`competitiv`,`elastic`],[`exchange rate`,`appreciat`,`inflation`,`depends`],[`primary`,`commodity`,`developing`]],`Dearer exports relative to imports means more imports per unit of exports. But if demand for exports is elastic, volumes fall and competitiveness suffers. It depends on why the terms moved, such as an exchange rate appreciation or a commodity boom.`,3,'h')]});
const EXG=GS([[40,140,200,30,'#dc2626','MPC'],[40,120,200,10,'#f59e0b','MSC'],[40,40,200,140,'#2563eb','D = MSB']],[[116,88],[101,78]],'Quantity','Price');
SB[1].th[0].t.push({id:'e8',n:'Externalities',gen:[],sum:`<h4>Definition</h4><p>An <b>externality</b> is a cost or benefit felt by a third party who is not part of the transaction. Markets ignore them, so the free market produces the wrong amount. This is <b>market failure</b>.</p><h4>Types</h4><ul><li><b>Negative production externality:</b> factory pollution.</li><li><b>Negative consumption externality:</b> smoking or loud music.</li><li><b>Positive externalities:</b> education and vaccinations.</li></ul><h4>Key terms</h4><ul><li><b>MPC:</b> marginal private cost. <b>MSC:</b> marginal social cost = MPC + external cost.</li><li><b>Social optimum:</b> where MSB = MSC.</li><li><b>Welfare loss:</b> the triangle showing overproduction.</li></ul>${EXG}<p class='sm'>MSC lies above MPC, so the market output (where MPC meets D) is above the social optimum (where MSC meets D).</p><h4>Fixing it</h4><ul><li><b>Indirect tax</b> (e.g. a carbon tax), <b>subsidies</b> for positives, <b>regulation</b>, <b>tradable permits</b>, education and nudges.</li></ul><h4>Evaluation</h4><p>External costs are hard to measure, taxes can be regressive, demand may be inelastic so output barely falls, and government failure is possible.</p>`,q:[M(`A cost felt by a third party is...`,[`A negative externality`,`A private benefit`,`Consumer surplus`,`A subsidy`],`Externalities affect people outside the transaction.`,'e'),M(`Which policy helps correct a negative externality?`,[`An indirect tax`,`A subsidy to the polluter`,`Removing regulation`,`A price floor`],`A tax raises the private cost towards the social cost.`,'m'),M(`With a negative externality, free market output is...`,[`Above the social optimum`,`Below the social optimum`,`At the social optimum`,`Zero`],`Producers ignore the external cost, so they overproduce.`,'h'),S_(`Evaluate the use of taxation to correct negative externalities. [12 marks] Explain how a tax works, assess its limits and alternatives, and reach a judgement.`,[[`tax`,`carbon`,`internalis`],[`external cost`,`msc`,`mpc`,`social`],[`inelastic`,`regressive`,`measure`,`difficult`,`government failure`],[`regulation`,`permits`,`subsid`]],`A tax raises private cost towards social cost, reducing output and raising revenue. But the external cost is hard to measure, inelastic demand means little change, and it can be regressive. Regulation or permits are alternatives.`,3,'h'),GQ(`Draw a diagram showing a negative externality of production. Show the welfare loss.`,[`Axes labelled Price and Quantity`,`MPC and MSC curves with MSC above MPC`,`Demand curve (MSB)`,`Market output Q1 and social optimum Q2 with Q2 less than Q1`,`Welfare loss area shaded`],EXG,'h')]});
SB[1].th[3].t.push({id:'e9',n:'Public sector finances',gen:[],sum:`<h4>Key terms</h4><ul><li><b>Budget deficit:</b> government spends more than it raises in a year.</li><li><b>National debt:</b> total accumulated borrowing.</li><li><b>Fiscal policy:</b> changing tax and spending.</li><li><b>Automatic stabilisers:</b> spending and taxes that adjust with the cycle, such as unemployment benefits.</li></ul><h4>Types of tax</h4><ul><li><b>Direct</b> (income tax) vs <b>indirect</b> (VAT).</li><li><b>Progressive</b> (rate rises with income), <b>regressive</b> (takes a bigger share from the poor), <b>proportional</b>.</li></ul><h4>Why debt matters</h4><ul><li>Interest payments, crowding out of private investment, and a burden on future taxpayers.</li></ul><h4>Evaluation</h4><p>Borrowing can make sense in a recession or to fund investment. What matters is debt as a % of GDP and whether growth outpaces interest costs.</p>`,q:[M(`A budget deficit is...`,[`Spending greater than tax revenue in a year`,`Total accumulated debt`,`A trade deficit`,`A fall in prices`],`The national debt is the stock; the deficit is the yearly flow.`,'e'),M(`Which tax is regressive?`,[`One that takes a larger share of income from the poor`,`Income tax with rising rates`,`A tax only on the rich`,`Corporation tax`],`VAT and similar taxes are often regressive.`,'m'),M(`Why does a recession tend to increase a budget deficit?`,[`Tax revenue falls and welfare spending rises`,`Tax revenue rises`,`Spending falls automatically`,`Debt is cancelled`],`Automatic stabilisers widen the deficit.`,'h'),S_(`Evaluate whether a government should reduce its budget deficit quickly. [12 marks] Analyse the benefits and costs, and reach a judgement.`,[[`spending cuts`,`tax rise`,`austerity`],[`growth`,`aggregate demand`,`recession`,`multiplier`],[`debt`,`interest`,`crowding out`],[`depends`,`long run`,`confidence`,`investment`]],`Quick cuts or tax rises lower debt and interest costs but reduce AD and growth, especially in a recession. It depends on the state of the economy, debt levels and market confidence.`,3,'h')]});
SB[1].th[3].t.push({id:'e10',n:'Poverty and inequality',gen:[],sum:`<h4>Poverty</h4><ul><li><b>Absolute poverty:</b> unable to afford basic needs such as food and shelter.</li><li><b>Relative poverty:</b> income below a set share (often 60%) of the median.</li></ul><h4>Inequality</h4><ul><li><b>Income</b> (a flow) vs <b>wealth</b> (a stock).</li><li><b>Gini coefficient:</b> 0 = perfect equality, 1 = one person has everything.</li><li><b>Lorenz curve:</b> the further from the 45 degree line, the more unequal.</li></ul><h4>Causes</h4><ul><li>Unemployment, low wages, education gaps, ageing population, discrimination, inherited wealth and globalisation.</li></ul><h4>Policies</h4><ul><li>Progressive taxes and benefits, minimum wage, education and training, regional investment.</li></ul><h4>Evaluation</h4><p>Redistribution can weaken incentives and growth, but extreme inequality harms social mobility and demand.</p>`,q:[M(`The Gini coefficient measures...`,[`Income inequality`,`Inflation`,`The trade balance`,`Unemployment`],`It ranges from 0 to 1.`,'e'),M(`A Gini coefficient of 0 means...`,[`Perfect equality`,`Perfect inequality`,`No poverty line`,`No growth`],`Everyone has the same income.`,'m'),M(`Relative poverty is best described as...`,[`Income below a set share of the median`,`Being unable to afford food`,`Having no wealth`,`Living in a developing country`],`Relative poverty depends on the average living standard.`,'h'),S_(`Evaluate policies to reduce income inequality. [12 marks] Analyse at least two policies, assess their drawbacks, and reach a judgement.`,[[`progressive tax`,`benefit`,`redistribut`],[`minimum wage`,`education`,`training`],[`incentive`,`growth`,`cost`,`disincentive`],[`depends`,`mobility`,`long run`]],`Progressive taxes and benefits redistribute income, and education raises earning power. But high taxes may weaken incentives and cost money. It depends on the policy mix and time horizon.`,3,'h')]});
const SPEC=(sid,i,a)=>{SB.find(s=>s.id==sid).th[i].spec=a};
