function sp(k,v){D.sp=D.sp||{};if(v)D.sp[k]=1;else delete D.sp[k];save()}
function specList(th){if(!th.spec)return '';let all=0,done=0,h=th.spec.map(([s,pts])=>`<p style='margin:12px 0 4px'><b>${s}</b></p>`+pts.split('|').map(p=>{let [pn,pid]=p.split('#'),k=th.n+'|'+s+'|'+pn,pk=pid?th.t.find(t=>t.id==pid):th.t.find(t=>t.n==pn),on=(D.sp||{})[k];all++;if(on)done++;return `<label style='display:flex;gap:10px;align-items:center;padding:6px 0'><input type='checkbox' ${on?'checked':''} onchange='sp(&quot;${k}&quot;,this.checked)'><span>${pk?`<a style='color:var(--p);font-weight:600' onclick='V=&quot;sum&quot;;A=&quot;${pk.id}&quot;;render()'>📦 ${pn}</a>`:pn}</span></label>`}).join('')).join('');return `<details style='padding-bottom:12px'><summary style='font-weight:600'>📋 Spec checklist · ${done}/${all} ticked</summary>${h}<p class='sm'>Tick points as you revise them. Packs (📦) are fully built. Built from the published specs from memory, so check against your official spec.</p></details>`}
const TL={term:'Term',q:'Question',c:'Fill the gap',tf:'True / False',f:'Formula',x:'Example',ch:'Chain',d:'Diagram'};
const PPFG=GS([],[],'Capital goods','Consumer goods').replace('</svg>',`<path d='M40 30 Q170 40 235 150' fill='none' stroke='#2563eb' stroke-width='3'/><circle cx='112' cy='45' r='4' fill='#22a85a'/><circle cx='80' cy='110' r='4' fill='#dc2626'/><circle cx='200' cy='60' r='4' fill='#6b7488'/><text x='118' y='42' font-size='10' fill='#22a85a'>efficient</text><text x='86' y='122' font-size='10' fill='#dc2626'>inefficient</text><text x='170' y='56' font-size='10' fill='#6b7488'>unattainable</text></svg>`);
const CSG=GS([[40,140,200,30,'#dc2626','S'],[40,40,200,140,'#2563eb','D']],[[116,88]],'Quantity','Price').replace('</svg>',`<polygon points='40,40 40,88 116,88' fill='#2563eb' opacity='.25'/><polygon points='40,88 116,88 40,140' fill='#22a85a' opacity='.3'/><text x='46' y='74' font-size='10' fill='currentColor'>CS</text><text x='46' y='112' font-size='10' fill='currentColor'>PS</text></svg>`);
const SUBG=GS([[40,140,200,30,'#dc2626','S1'],[40,160,200,50,'#22a85a','S2 (subsidy)'],[40,40,200,140,'#2563eb','D']],[[116,88],[131,97]],'Quantity','Price');
const H=(id,n,sum,q,cards)=>SB[1].th[0].t.push({id,n,gen:[],sum,q,cards});
H('h1','Economics as a social science, positive and normative',`<h4>Thinking like an economist</h4><p>Economics is a <b>social science</b>: it studies how people, firms and governments make choices. Economists build <b>models</b> that simplify reality using <b>assumptions</b>. The <b>ceteris paribus</b> assumption (all else equal) lets us isolate one change, such as the effect of price on demand. Economists cannot run controlled <b>experiments</b> on whole economies, so they rely on data, theory and judgement.</p><h4>Positive vs normative</h4><ul><li><b>Positive</b> statements can be tested with evidence, e.g. 'Unemployment fell to 4%'.</li><li><b>Normative</b> statements are opinions about what should happen, e.g. 'The government should raise the minimum wage'.</li><li><b>Value judgements</b> shape economic decisions and policy.</li></ul>`,[M(`Which is a positive statement?`,[`Inflation rose to 3% last year`,`The government should cut taxes`,`Rich people should pay more tax`,`Unemployment is too high`],`Positive statements can be tested with evidence.`,'e'),M(`Ceteris paribus means...`,[`All other things remain equal`,`Prices always rise`,`Supply equals demand`,`Costs are fixed`],`It lets economists isolate one variable.`,'e'),M(`Why can economists not easily run scientific experiments?`,[`They cannot control all variables in a whole economy`,`Economics has no data`,`Experiments are illegal`,`Models are never used`],`Economies are too complex to control.`,'m'),M(`A value judgement in economic policy is...`,[`An opinion about what is desirable that influences decisions`,`A statement that can be proved true`,`A GDP calculation`,`An assumption of perfect information`],`Normative views rest on value judgements.`,'h')],[['c','Fill the gap: A ____ statement can be tested against evidence.','positive'],['c','Fill the gap: The ____ ____ assumption holds all other factors constant.','ceteris paribus'],['tf','True or false: The government should raise taxes is a positive statement.','False - it is normative (an opinion).'],['x','Give a positive and a normative statement about the minimum wage.','Positive: A higher minimum wage raises hourly pay. Normative: The minimum wage should be higher.']]);
H('h2','The economic problem and PPFs',`<h4>The economic problem</h4><p><b>Scarcity</b> means unlimited wants but finite resources, so choices must be made. <b>Opportunity cost</b> is the next best alternative given up, e.g. money spent on defence cannot be spent on schools. Resources can be <b>renewable</b> (wind, timber) or <b>non-renewable</b> (oil, coal).</p><h4>Production possibility frontier (PPF)</h4><ul><li>Shows the <b>maximum productive potential</b>: combinations of two goods an economy can produce with all resources used efficiently.</li><li>On the curve = efficient; inside = inefficient or unemployed resources; outside = <b>unattainable</b>.</li><li>The slope shows <b>opportunity cost</b>; a bowed-out curve means rising opportunity cost.</li><li><b>Movement along</b> = choosing a different mix. <b>Outward shift</b> = growth (more resources, better technology). Inward = decline (war, disaster).</li><li><b>Capital goods</b> help future growth; <b>consumer goods</b> satisfy wants today.</li></ul>${PPFG}`,[M(`A point inside the PPF shows...`,[`Inefficient use or unemployed resources`,`Maximum efficiency`,`An unattainable output`,`Economic growth`],`Resources are not fully or efficiently used.`,'e'),M(`What would shift the PPF outwards?`,[`Improved technology`,`A natural disaster`,`A fall in the labour force`,`A fall in demand`],`More or better resources raise productive potential.`,'m'),M(`Opportunity cost is...`,[`The next best alternative given up`,`The money price of a good`,`The total cost of production`,`The cost of all alternatives`],`It is the value of the best forgone option.`,'m'),M(`Which resource is non-renewable?`,[`Oil`,`Timber`,`Wind`,`Sustainably managed fish`],`Non-renewable resources are used up.`,'h'),GQ(`Draw a PPF for capital goods and consumer goods. Show an unattainable point and an outward shift.`,[`Axes labelled with the two goods`,`Curve bowed outwards`,`Point on the curve = efficient`,`Point outside the curve labelled unattainable`,`Second PPF further out showing growth`],PPFG,'m')],[['c','Fill the gap: Scarcity is the problem of ____ wants and ____ resources.','unlimited; finite'],['f','Opportunity cost along a PPF','Units of one good given up per extra unit of the other. Example: gain 20 units of X, lose 10 of Y, so each X costs 0.5 Y.'],['tf','True or false: A point outside the PPF is attainable with current resources.','False - it is unattainable until the economy grows.'],['d','Diagram: a PPF with efficient, inefficient and unattainable points',PPFG],['x','Give a real-world cause of an outward PPF shift.','New technology such as automation, or a more educated workforce.']]);
H('h3','Specialisation, money and economic systems',`<h4>Specialisation and division of labour</h4><p>Adam Smith argued that when workers <b>specialise</b> in one task (<b>division of labour</b>) output rises through practice, less time switching tasks and use of machines. <b>Disadvantages:</b> boredom, dependence on others, structural unemployment if skills become obsolete. Countries gain by specialising in goods with the lowest opportunity cost, then trading.</p><h4>Functions of money</h4><ul><li><b>Medium of exchange</b>, <b>measure of value</b>, <b>store of value</b>, <b>method of deferred payment</b>.</li></ul><h4>Economic systems</h4><ul><li><b>Free market</b> (Adam Smith, Friedrich Hayek): prices allocate resources and ownership is private. Pros: efficiency, choice, incentives. Cons: inequality, market failure.</li><li><b>Command economy</b> (Karl Marx): the state plans and owns resources. Pros: aims at equality. Cons: shortages, weak incentives.</li><li><b>Mixed economy</b>: market plus state (the UK). The state provides public goods, regulates and redistributes.</li></ul>`,[M(`Which is a function of money?`,[`Store of value`,`Factor of production`,`A public good`,`A subsidy`],`The four functions are exchange, measure of value, store of value and deferred payment.`,'e'),M(`Who wrote about the division of labour?`,[`Adam Smith`,`Karl Marx`,`Friedrich Hayek`,`Alfred Marshall`],`Adam Smith used the example of a pin factory.`,'e'),M(`A disadvantage of specialisation is...`,[`Workers' skills may become obsolete`,`Output always falls`,`It removes trade`,`Prices always rise`],`Narrow skills can leave workers unemployed if demand changes.`,'m'),M(`In which system does the state plan and own most resources?`,[`Command economy`,`Free market`,`Mixed economy`,`Perfect competition`],`Karl Marx is linked to this approach.`,'h')],[['c','Fill the gap: In a ____ economy the price mechanism allocates most resources.','free market'],['tf','True or false: The UK is a pure free market economy.','False - it is a mixed economy.'],['x','Give an example of the division of labour.','A car factory where workers each do one task on the assembly line.'],['ch','Chain: why does specialisation raise output?','Workers focus on one task, gain skill and speed, lose less time switching, so output per worker rises.'],['term','List the four functions of money.','Medium of exchange, measure of value, store of value, method of deferred payment.']]);
H('h4','Rational decision making and demand',`<h4>Rational decision making</h4><p>Economics assumes <b>consumers</b> aim to maximise <b>utility</b> (satisfaction) and <b>firms</b> aim to maximise <b>profits</b>.</p><h4>Demand</h4><ul><li><b>Demand</b> = willingness and ability to buy at each price. Price up, quantity demanded down.</li><li><b>Movement along</b> the curve is caused by a price change. A <b>shift</b> is caused by the <b>conditions of demand</b>: income, tastes, prices of substitutes and complements, population, advertising, expectations.</li><li><b>Diminishing marginal utility:</b> each extra unit gives less extra satisfaction, so people will pay less for extra units. This explains the downward-sloping demand curve.</li></ul>${DSG('S','D','Quantity','Price')}<p class='sm'>A rise in income shifts demand right (D1 to D2).</p>`,[M(`Consumers are assumed to aim to maximise...`,[`Utility`,`Profit`,`Revenue`,`Output`],`Firms are assumed to maximise profit.`,'e'),M(`Which causes a shift of the demand curve?`,[`A change in income`,`A change in the good's own price`,`A movement along supply`,`A price-driven change in quantity demanded`],`Own price changes cause movements along the curve.`,'m'),M(`Diminishing marginal utility means...`,[`Each extra unit gives less additional satisfaction`,`Total utility falls`,`Prices fall automatically`,`Supply decreases`],`This is why demand slopes downward.`,'m'),M(`A rise in the price of a complement will...`,[`Shift demand for the good left`,`Shift demand right`,`Shift supply left`,`Raise quantity demanded`],`E.g. dearer printers reduce demand for ink.`,'h')],[['tf','True or false: A fall in a good\'s own price shifts its demand curve right.','False - it causes a movement along the curve.'],['c','Fill the gap: Demand slopes downward partly because of diminishing ____ ____.','marginal utility'],['d','Diagram: a rightward shift of demand',DSG('S','D','Quantity','Price')],['ch','Chain: incomes rise (normal good)','Demand shifts right, excess demand at the old price, price rises, quantity supplied extends, higher equilibrium price and quantity.']]);
H('h5','Elasticity of supply',`<h4>Definition</h4><p><b>Price elasticity of supply (PES)</b> measures how much quantity supplied responds to a price change.</p><p class='f'>PES = %change in quantity supplied ÷ %change in price</p><ul><li>Above 1 = <b>elastic</b>, below 1 = <b>inelastic</b>, 0 = perfectly inelastic, infinity = perfectly elastic.</li></ul><h4>Factors</h4><ul><li><b>Spare capacity</b>, <b>stocks</b> of finished goods, how easily production can switch, number of firms, availability of factors, and <b>time</b>: supply is more elastic in the <b>long run</b> than the <b>short run</b>.</li></ul><h4>Real-world example</h4><p>Farm crops have inelastic supply in the short run (wheat cannot be grown overnight); a software download is close to perfectly elastic.</p>`,[M(`PES = ...`,[`%change in quantity supplied ÷ %change in price`,`%change in price ÷ %change in quantity supplied`,`Change in revenue ÷ change in price`,`Change in demand ÷ change in income`],`PES measures supply responsiveness.`,'e'),M(`Price rises 10% and quantity supplied rises 5%. PES is...`,[`0.5`,`2`,`5`,`50`],`5 ÷ 10 = 0.5 (inelastic).`,'m'),M(`Which makes supply more elastic?`,[`Spare capacity`,`A short time period`,`No stocks`,`Few ways to switch production`],`Firms can raise output quickly.`,'m'),M(`Why is agricultural supply inelastic in the short run?`,[`Crops take time to grow`,`Farmers have no costs`,`Demand is fixed`,`Supply is perfectly elastic`],`Time is the key factor in elasticity of supply.`,'h')],[['f','Formula: PES','PES = %change in quantity supplied ÷ %change in price. Example: price +10%, quantity supplied +20%, PES = 2 (elastic).'],['c','Fill the gap: Supply is more elastic in the ____ run.','long'],['tf','True or false: A PES of 0.3 means supply is elastic.','False - below 1 means inelastic.'],['x','Give an example of inelastic supply.','Wheat in the short run, because crops take months to grow.']]);
H('h6','Price mechanism',`<h4>Functions of the price mechanism</h4><ul><li><b>Rationing:</b> high prices limit demand when goods are scarce.</li><li><b>Incentive:</b> higher prices encourage firms to supply more and buyers to look for alternatives.</li><li><b>Signalling:</b> price changes tell firms where demand is rising or falling.</li></ul><h4>Real-world examples</h4><p>Concert tickets: high demand raises the price and rations tickets. A rise in the price of lithium signals firms to supply more and look for substitutes.</p><h4>Different markets</h4><p>It works in <b>local</b> (a farmers market), <b>national</b> (housing) and <b>global</b> markets (oil).</p><h4>Evaluation</h4><p>It ignores those who cannot afford the price and fails with externalities or information gaps.</p>`,[M(`Which is a function of the price mechanism?`,[`Rationing`,`Taxation`,`Redistribution`,`Regulation`],`The three functions are rationing, incentive and signalling.`,'e'),M(`A rise in price signals to firms to...`,[`Produce more`,`Produce less`,`Leave the market`,`Cut costs only`],`Higher prices signal higher profit potential.`,'m'),M(`High ticket prices for a sold-out concert show the price mechanism...`,[`Rationing a scarce good`,`Subsidising consumers`,`Reducing demand to zero`,`Setting a minimum price`],`Only those willing and able to pay get tickets.`,'m'),M(`Which is a weakness of the price mechanism?`,[`It ignores those who cannot afford the price`,`It gives signals`,`It rewards efficiency`,`It uses incentives`],`It does not consider fairness.`,'h')],[['term','Name the three functions of the price mechanism.','Rationing, incentive, signalling.'],['c','Fill the gap: Rising prices act as a ____ to firms to supply more.','signal (incentive)'],['ch','Chain: demand for electric cars rises','Demand rises, price rises, profits signal firms, more firms enter and produce, supply increases, price eases.'],['tf','True or false: The price mechanism only works in national markets.','False - it works in local, national and global markets.']]);
H('h7','Consumer and producer surplus',`<h4>Definitions</h4><ul><li><b>Consumer surplus:</b> what consumers are willing to pay minus what they actually pay (area under demand, above price).</li><li><b>Producer surplus:</b> the price producers receive minus the minimum they would accept (area above supply, below price).</li></ul>${CSG}<p class='sm'>CS = consumer surplus, PS = producer surplus.</p><h4>Changes</h4><ul><li>A price cut raises consumer surplus.</li><li>Higher costs shift supply left, raising price and cutting consumer surplus.</li><li>A rise in demand raises price and producer surplus.</li></ul>`,[M(`Consumer surplus is...`,[`What consumers are willing to pay minus what they pay`,`What producers receive minus costs`,`Total revenue`,`Profit`],`It measures consumer benefit.`,'e'),M(`On a supply and demand diagram, producer surplus lies...`,[`Above supply and below the price`,`Below supply`,`Above demand`,`Under demand and above price`],`It is the area between price and the supply curve.`,'m'),M(`A rise in price caused by a fall in supply will usually...`,[`Reduce consumer surplus`,`Raise consumer surplus`,`Have no effect on surplus`,`Remove producer surplus`],`Consumers pay more for fewer goods.`,'m'),GQ(`Draw a supply and demand diagram. Shade consumer and producer surplus at equilibrium.`,[`Axes labelled Price and Quantity`,`Demand and supply curves`,`Equilibrium price and quantity marked`,`Consumer surplus shaded above price under demand`,`Producer surplus shaded below price above supply`],CSG,'m')],[['c','Fill the gap: Consumer surplus is the area ____ the demand curve and ____ the price.','below; above'],['tf','True or false: Producer surplus is the area below the supply curve.','False - it is above supply and below price.'],['d','Diagram: consumer and producer surplus',CSG]]);
H('h8','Indirect taxes and subsidies',`<h4>Indirect taxes</h4><ul><li>A tax on goods and services (e.g. VAT, fuel duty) raises costs and shifts supply <b>left (up)</b>. Price rises, quantity falls.</li><li><b>Incidence</b> = who pays. If demand is <b>inelastic</b>, consumers bear more of the tax; if demand is elastic, producers bear more.</li><li>Government revenue = tax per unit × quantity sold.</li></ul>${TAXG}<h4>Subsidies</h4><ul><li>Payments to producers that lower costs and shift supply <b>right (down)</b>. Price falls, quantity rises. The government pays the <b>subsidy area</b>.</li><li>With inelastic demand most of the benefit goes to consumers as a lower price.</li></ul><h4>Evaluation</h4><p>Taxes can cut demerit goods but may be regressive; subsidies cost taxpayers and may prop up inefficient firms.</p>`,[M(`An indirect tax shifts the supply curve...`,[`Left (upward)`,`Right`,`Down only`,`It does not shift`],`The tax raises costs of supply.`,'e'),M(`With inelastic demand, an indirect tax is mostly paid by...`,[`Consumers`,`Producers`,`The government`,`Nobody`],`Inelastic buyers cannot easily switch.`,'m'),M(`A subsidy to producers will usually...`,[`Lower price and raise quantity`,`Raise price`,`Lower quantity`,`Shift demand left`],`Supply shifts right.`,'m'),M(`Government revenue from an indirect tax is shown by...`,[`Tax per unit × quantity sold`,`Consumer surplus`,`Total cost`,`Price × demand`],`It is the tax rectangle.`,'h'),GQ(`Draw a diagram showing the effect of a subsidy on a market.`,[`Axes labelled Price and Quantity`,`Original S1 and demand`,`Supply shifts right/down to S2`,`Lower price and higher quantity shown`,`Subsidy area identified`],SUBG,'h')],[['tf','True or false: An indirect tax shifts supply to the right.','False - it shifts supply left (up).'],['ch','Chain: a tax on sugary drinks','Tax raises costs, supply shifts left, price rises, quantity demanded falls (more if demand is elastic), government gains revenue.'],['d','Diagram: an indirect tax',TAXG],['c','Fill the gap: The ____ of a tax shows who actually pays it.','incidence'],['d','Diagram: a subsidy',SUBG]]);
H('h9','Alternative views of consumer behaviour',`<h4>Why consumers may not behave rationally</h4><ul><li><b>Influence of other people:</b> social norms, peer pressure and <b>herd behaviour</b> (buying what others buy).</li><li><b>Habitual behaviour:</b> repeating past choices without weighing alternatives (same brand, same route).</li><li><b>Weakness at computation:</b> struggling to compare complex options such as mobile contracts or mortgages, so using rules of thumb.</li></ul><h4>Why it matters</h4><p>Firms use advertising and default options. Governments use <b>nudges</b>, e.g. automatically enrolling workers in pensions with an opt-out. It challenges the assumption of rational utility maximisation.</p>`,[M(`Herd behaviour is when consumers...`,[`Copy what other people do`,`Always compare all prices`,`Buy only the cheapest`,`Avoid advertising`],`Others' choices influence decisions.`,'e'),M(`Habitual behaviour means...`,[`Repeating past choices without much thought`,`Always changing brands`,`Calculating utility each time`,`Buying only on credit`],`Habits can stop people reviewing alternatives.`,'m'),M(`Which supports the view that consumers are not always rational?`,[`Struggling to compare complex contracts`,`Perfect information`,`Always maximising utility`,`Perfect computation`],`This is weakness at computation.`,'m'),M(`A default pension opt-out scheme is an example of...`,[`A nudge`,`A subsidy`,`A tax`,`A price control`],`Defaults steer choices without forcing them.`,'h')],[['c','Fill the gap: Following what others do is called ____ behaviour.','herd'],['tf','True or false: Habits always lead consumers to the best option.','False - habits can stop people reviewing better alternatives.'],['x','Give an example of weakness at computation.','Struggling to compare complex mobile contracts and choosing without full analysis.']]);
H('h10','Types of market failure, public goods and information gaps',`<h4>Market failure</h4><p>Market failure is when the free market <b>misallocates resources</b>, producing too much or too little. Types: <b>externalities</b>, <b>under-provision of public goods</b> and <b>information gaps</b>.</p><h4>Public goods</h4><ul><li><b>Non-rivalrous:</b> one person's use does not reduce availability. <b>Non-excludable:</b> you cannot stop people using it.</li><li><b>Pure public goods:</b> street lighting, national defence, flood defences. <b>Private goods</b> are rival and excludable (a sandwich).</li><li><b>Free rider problem:</b> people use it without paying, so firms cannot make profit and under-provide it. The state usually provides it, funded by tax.</li></ul><h4>Information gaps</h4><ul><li><b>Symmetric</b> information: both sides know the same. <b>Asymmetric:</b> one side knows more (used cars, insurance).</li><li>Imperfect information can lead to over or under consumption and a <b>misallocation of resources</b>, e.g. smokers underestimating health risks.</li></ul>`,[M(`A pure public good is...`,[`Non-rivalrous and non-excludable`,`Rivalrous and excludable`,`Always free`,`Provided only by firms`],`Both features lead to the free rider problem.`,'e'),M(`Which is an example of a public good?`,[`Street lighting`,`A pizza`,`A phone`,`A haircut`],`Street lighting is non-rivalrous and non-excludable.`,'e'),M(`The free rider problem occurs when...`,[`People use a good without paying`,`Firms charge too much`,`Everyone pays`,`Supply is elastic`],`So firms cannot earn profit.`,'m'),M(`Asymmetric information means...`,[`One party knows more than the other`,`Both know everything`,`Information is free`,`Prices are fixed`],`E.g. a used car seller vs the buyer.`,'m'),M(`Why might private firms under-provide public goods?`,[`They cannot easily charge users, so profit is hard`,`Demand is zero`,`Supply is infinite`,`They are always profitable`],`Non-excludability stops firms charging.`,'h'),S_(`Explain why public goods may not be provided by the private sector. [6 marks] Use the free rider problem.`,[[`free rider`,`without paying`],[`non-excludable`,`cannot exclude`,`cannot stop`],[`profit`,`revenue`,`charge`],[`government`,`tax`,`state`]],`Public goods are non-excludable, so free riders use them without paying. Firms cannot charge and make profit, so they under-provide; the government provides them funded by taxes.`,3,'m')],[['tf','True or false: A pure public good is rivalrous.','False - public goods are non-rivalrous and non-excludable.'],['c','Fill the gap: The ____ ____ problem leads to under-provision of public goods.','free rider'],['x','Give an example of asymmetric information.','A used car seller knows more about the car than the buyer.'],['term','Rivalrous vs non-rivalrous?','Rivalrous: one person using it reduces availability for others. Non-rivalrous: it does not.'],['ch','Chain: why defence is provided by the state','Non-excludable, so free riders, so firms cannot charge, private provision fails, government provides it funded by taxes.']]);
tp('e1').cards=[['f','Formula: PED','PED = %change in quantity demanded ÷ %change in price. Example: price +10%, quantity demanded -25%, PED = -2.5 (elastic).'],['f','Formula: YED','YED = %change in quantity demanded ÷ %change in income. Positive = normal good (above 1 = luxury); negative = inferior good.'],['f','Formula: XED','XED = %change in quantity demanded of A ÷ %change in price of B. Positive = substitutes; negative = complements; near 0 = unrelated.'],['d','Diagram: elastic vs inelastic demand',PEDG],['tf','True or false: If PED is -0.4, a price rise increases total revenue.','True - demand is inelastic, so quantity falls proportionately less.'],['ch','Chain: price falls when demand is elastic','Price falls, quantity demanded rises by a larger percentage, total revenue rises.'],['c','Fill the gap: A PED of exactly 1 is called ____ elastic.','unit']];
tp('e8').cards=[['c','Fill the gap: A cost borne by a third party is an external ____.','cost'],['d','Diagram: negative externality of production',EXG],['tf','True or false: Education creates a positive externality.','True - others benefit, e.g. a more skilled workforce.'],['x','Give an example of a positive externality of consumption.','Vaccination also protects other people.']];
