function cardPool(){let L=[],seen={};T.forEach(t=>{if(FC.sc!='all'&&t.s!=FC.sc)return;if(FC.tp!='all'&&t.id!=FC.tp)return;let re=/<b>([^<]{2,50}?):?<[/]b>:?[ ]*([^<]{15,300})/g,m;while(m=re.exec(t.sum||'')){L.push({f:'Define / explain: '+m[1].replace(/[: ]+$/,''),b:m[2].replace(/^[ :–-]+/,''),t:t.n,ty:'term'})}(t.cards||[]).forEach(([ty,f,b])=>L.push({f,b,t:t.n,ty}));t.q.forEach(q=>{if(q.k=='m')L.push({f:q.q,b:q.o[0]+'. '+q.e,t:t.n,ty:'q'});else if(q.k=='s')L.push({f:q.q,b:q.m,t:t.n,ty:'q'})})});return L.filter(c=>{if(FC.ty!='all'&&c.ty!=FC.ty)return 0;c.id=hs(c.f+c.t);if(seen[c.id])return 0;seen[c.id]=1;return 1})}
function nextCard(){let gt=T.filter(t=>t.gen&&t.gen.length&&(FC.sc=='all'||t.s==FC.sc)&&(FC.tp=='all'||t.id==FC.tp));if(gt.length&&(FC.ty=='all'||FC.ty=='q')&&Math.random()<.3){let t=rn(gt),q=mk(rn(t.gen),rn(['e','m','h']));return{f:q.q,b:q.o[0]+' - '+q.e,t:t.n,gen:1}}let w=FC.pool.map(c=>5-((D.cards||{})[c.id]||0)),r=Math.random()*w.reduce((a,b)=>a+b,0),i=0;while(i<w.length-1&&(r-=w[i])>0)i++;return FC.pool[i]}
