function fcStart(){let pl=FC.md=='f'?Array.from({length:FC.np},(_,i)=>(FC.nm[i]||'').trim()||'Player '+(i+1)):['You'];FC.pl=pl;FC.pts={};pl.forEach(n=>FC.pts[n]=0);FC.on=1;FC.turn=0;FC.n=0;FC.pool=cardPool();FC.cur=nextCard();FC.flip=0;render()}
