function gs(v){v=v.toLowerCase().trim();let r=$('sr');if(v.length<3){r.innerHTML='';return}let s=FC.sc,t=FC.tp;FC.sc='all';FC.tp='all';let L=cardPool();FC.sc=s;FC.tp=t;r.innerHTML=L.filter(c=>(c.f+c.b).toLowerCase().includes(v)).slice(0,15).map(c=>`<div class='card'><b>${c.f}</b><p class='sm'>${c.t}</p><p>${c.b}</p></div>`).join('')||`<p class='sm'>No matches.</p>`}
