const lev=(a,b)=>{let m=a.length,n=b.length,d=[...Array(m+1)].map((_,i)=>{let r=Array(n+1).fill(0);r[0]=i;return r});for(let j=0;j<=n;j++)d[0][j]=j;for(let i=1;i<=m;i++)for(let j=1;j<=n;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]==b[j-1]?0:1));return d[m][n]};
function gs2(v){SQ.q=v;let r=$('sr'),ws=nz(v);if(!ws.length){r.innerHTML='';return}let s0=FC.sc,t0=FC.tp,y0=FC.ty;FC.sc='all';FC.tp='all';FC.ty='all';let L=cardPool();FC.sc=s0;FC.tp=t0;FC.ty=y0;const mf=(a,w)=>a.some(t=>t==w)?3:a.some(t=>t.startsWith(w))?2:(w.length>=5&&a.some(t=>t.length>=5&&lev(w,t)<=1))?1:0,ph=v.toLowerCase().trim(),sc=x=>{let ft=nz(x.f),bt=nz(x.b),tt=nz(x.t),all=1,s=0;ws.forEach(w=>{let a=mf(ft,w),b=mf(bt,w),c=mf(tt,w);if(!a&&!b&&!c)all=0;s+=4*a+1.5*b+c});if((x.f+' '+x.b).toLowerCase().includes(ph))s+=6;return all?s:s/4};let R=L.map(c=>({c,p:T.find(q=>q.n==c.t),s:sc(c)})).filter(o=>o.s>0&&(SQ.sc=='all'||(o.p&&o.p.s==SQ.sc))).sort((a,b)=>b.s-a.s).slice(0,12),TH=T.filter(t=>(SQ.sc=='all'||t.s==SQ.sc)&&ws.every(w=>mf(nz(t.n),w)>0)).slice(0,3),hl=s=>s.replace(new RegExp('('+ws.join('|')+')','gi'),'<mark>$1</mark>');r.innerHTML=`<div>${[['all','All'],['rs','RS'],['eco','Economics'],['med','Media']].map(([k,l])=>`<button class='ln' style='${SQ.sc==k?'background:var(--p);color:#fff':''}' onclick='SQ.sc=&quot;${k}&quot;;gs2(SQ.q)'>${l}</button>`).join('')}</div>`+TH.map(t=>`<div class='card'>📦 <b>${t.n}</b><br><button class='ln' onclick='V=&quot;sum&quot;;A=&quot;${t.id}&quot;;render()'>Open summary</button><button class='ln' onclick='go([&quot;${t.id}&quot;],&quot;a&quot;,&quot;${t.n}&quot;)'>Practise</button></div>`).join('')+(R.length?R.map(o=>`<div class='card'><b>${hl(o.c.f)}</b><p class='sm'>${o.c.t}</p><p>${hl(o.c.b)}</p></div>`).join(''):`<p class='sm'>No matches. Try fewer words or a different spelling.</p>`)}
