let MT={n:['Player 1','Player 2'],av:[0,12],sc:'all',th:'all',tp:'all',on:0,r:0,p:[0,0],a:[null,null],rp:[0,0],ph:'',q:null,o:[],t0:0,qs:[],to:0,done:0};
