function qmStart(){let ts=T.filter(t=>(MT.sc=='all'||t.s==MT.sc)&&(MT.th=='all'||SB.find(s=>s.id==MT.sc).th[+MT.th].t.includes(t))&&(MT.tp=='all'||t.id==MT.tp)),pool=[];ts.forEach(t=>{t.q.forEach(q=>{if(q.k=='m')pool.push(q)});(t.gen||[]).forEach(ty=>{for(let i=0;i<4;i++)pool.push(mk(ty,rn(['e','m','h'])))})});if(!pool.length)return;let L=sh(pool);while(L.length<10)L=L.concat(sh(pool));MT.qs=L.slice(0,10);MT.on=1;MT.r=0;MT.p=[0,0];MT.done=0;qmRound()}
function qmRound(){MT.q=MT.qs[MT.r];MT.o=sh([0,1,2,3]);MT.a=[null,null];MT.rp=[0,0];MT.t0=Date.now();MT.ph='q';clearTimeout(MT.to);MT.to=setTimeout(qmEnd,15000);render()}
