 if(q.k=='m'){let o=S.o[q.id]||(S.o[q.id]=sh([0,1,2,3]));h+=o.map((x,j)=>`<label class="opt" id="o${j}"><input type="radio" name="a" value="${j}"> <b>${'ABCD'[j]}.</b> ${q.o[x]}</label>`).join('')}
 else if(q.k=='g')h+=`<p class='sm'>Draw with your finger or Apple Pencil. Axes are pre-drawn.</p><div style='display:flex;gap:8px'><button class='ln' onclick='tool(0)'>✏️ Pen</button><button class='ln' onclick='tool(1)'>🧽 Eraser</button><button class='ln' onclick='clr()'>🗑 Clear</button></div><canvas id='cv' width='600' height='420' style='width:100%;touch-action:none;border:2px solid var(--b);border-radius:14px;background:#fff;margin-top:8px'></canvas>`;else h+=`<textarea id="ta" rows="4" placeholder="Type your answer..."></textarea>`;
