  let x12=q.q.includes('[12 marks]')?1:0,G=x12?[...q.g,[`overall`,`on balance`,`therefore`,`depends`,`however`,`conclusion`,`weighing`,`in my judgement`]]:q.g;G.forEach(g=>(g.some(w=>mt(t,w))?hit:miss).push(g[0]));ok=hit.length>=q.n+x12;
