function res(){let n=S.ids.length,pct=Math.round(S.sc/n*100),tc=Object.entries(S.tc).map(([t,[c,k]])=>[t,c/k]).sort((a,b)=>b[1]-a[1]),b=tc[0],w=tc[tc.length-1];
 let msg=pct>=90?'Outstanding work!':pct>=70?'Solid session - keep pushing.':pct>=50?'Getting there. Review the misses below and go again.':'Tough one, but this is how you learn. Check the answers and try again.';
 $('mn').innerHTML=`<h1>Results</h1><div class="card"><div class="big">${S.sc}/${n} (${pct}%)</div><p>⚡ Speed points: <b>${S.pt||0}</b> / ${n*100}</p><p>${msg}</p>
 <p><b>Strongest area:</b> ${b?TM[b[0]].n:'-'}<br><b>Needs improving:</b> ${w&&w[1]<1?TM[w[0]].n:'Nothing - great session'}</p>
 <b>Topic mastery</b>${S.tids.map(i=>{let x=ts(TM[i]);return `<div class="sm" style="margin-top:8px">${TM[i].n}: ${x.m}/${x.n}</div>${bar(x.mp)}`}).join('')}</div>
 ${S.wr.length?`<div class="card"><h3 style="margin-top:0">Questions to review</h3>`+S.wr.map(id=>{let q=QM[id];return `<p><b>${q.q}</b><br><span class="ok">${q.k=='m'?q.o[0]+' - '+q.e:q.k=='g'?q.chk.join('; '):q.m}</span></p>`}).join('')+`</div>`:''}
 <button class="btn" onclick="go(S.tids,S.mode,S.title)">Continue revising</button>${pct>=90&&DIF!='h'?`<button class="btn" onclick="DIF='${DIF=='e'?'m':'h'}';go(S.tids,S.mode,S.title)">🔥 Smashed it - try ${DIF=='e'?'Medium':'Hard'}</button>`:''}<button class="btn alt" onclick="V='home';render()">Finish for now</button>`}

function nav(k){V=k;render()}
function render(){$('mn').className=(window.LV!==V?'pg':'');window.LV=V;$('nv').innerHTML='<h2>'+LOGO+' Gideons Revision</h2>'+NV.map(([k,l])=>`<a class="${V==k||(V=='sub'&&k=='subs')?'on':''}" onclick="nav('${k}')">${l.replace(' ',' <br>')}</a>`).join('');
 if(V=='q')showQ();else if(V=='res')res();else $('mn').innerHTML=({home,subs,prog,set,sub:()=>sub(A),sum:()=>summ(A),cards:()=>cards(),daily:()=>daily()})[V]();scrollTo(0,0)}
render();
lbInit();
